(window.MUSEUM_READ_T = window.MUSEUM_READ_T || {})["zh"] = {"ui":{"lead":"游戏是怎样被发现、被遗忘、被解读、又被改变的？读完{n}个故事，答对结尾小测验的全部题目，就能得到一枚印章。","card":"印章卡","cardN":"已收集 {n} / {of}","cardAll":"全部集齐！","no":"故事 {n}","mins":"约{n}分钟","stamped":"已盖章","back":"全部故事","quiz":"小测验","links":"看展品・玩游戏","game":"游戏","exhibit":"馆藏","art":"绘画","room":"展厅","room_chance":"掷具","qn":"第 {n} / {of} 题","right":"答对了！","wrong":"可惜……正确答案已标出。","got":"盖章成功！","again":"全部答对！","gotSub":"已记录在印章卡上。","missed":"答错 {n} 题","retrySub":"全部答对才能得到印章。再读一遍故事，重新挑战吧。","retry":"再挑战","room_paint":"画中游戏","room_map":"地图","kfH":"本篇要点","tlH":"年表","refH":"出处与参考","picLink":"打开博物馆的作品页面"},"ex":{"ur":"乌尔王族游戏盘","liubo":"六博棋盘与棋子","pyrgus":"罗马掷骰塔","sugoroku":"木画紫檀双六局","nishapur":"内沙布尔国际象棋","lewis":"刘易斯岛棋子","senet":"图坦卡蒙的塞尼特棋盘","ballinderry":"巴林德里游戏盘","goose":"国际象棋与鹅棋棋盘","kofukuji":"兴福寺旧址出土的将棋棋子","shosoin":"木画紫檀棋局"},"paint":{"liubo":"博戏俑（随葬像）","sugoroku":"打双六的两位少女","shahnama":"布祖尔吉米赫尔解国际象棋","nefertari":"下塞尼特棋的奈费尔塔利王后","chaupar":"下乔帕尔的湿婆与帕尔瓦蒂","shogi":"下将棋的年轻男女","hydria":"下棋的阿喀琉斯与埃阿斯（水罐）","eakins":"下国际象棋的人","weiqi":"仙人对弈图盘","webb":"双陆棋手（陈列柜）","liberale":"下棋的人们","mirror":"下国际象棋的恋人镜盒","morris":"莫里斯棋（九子棋）棋盘","leifeng":"雷峰塔棋盘","teniers":"双陆对局","imari":"下围棋的两人方盘","shoei":"琴棋书画图屏风","tutinama":"咬了棋友王子的猴子（莫卧儿宫廷，约1560年）"},"ur":{"title":"4500年前的规则是如何被解读的","lead":"乌尔王陵出土的棋盘没有留下玩法。线索藏在两千多年后的一块泥板上。","s":["20世纪20年代，伦纳德・伍利在伊拉克南部的乌尔发掘王族墓葬，发现了一块用贝壳和青金石装饰的20格棋盘，年代约为公元前2600—前2400年。中东各地都出土过类似的棋盘，可见这种游戏流传既广又久。","然而，与它一起出土的没有任何讲玩法的记录。有棋盘、棋子和骰子，却不知道规则——这是古代游戏常有的事。","线索在大英博物馆的库房里：一块楔形文字泥板，由巴比伦书吏伊蒂-马尔杜克-巴拉图于公元前177/176年，从一位名叫伊丁-贝尔的人的泥板上抄写而来。它比棋盘晚了两千多年。","20世纪80年代初，大英博物馆的欧文・芬克尔意识到，这块泥板写的正是同一种20格游戏。泥板背面画着棋盘，并写有停在各格时的吉凶。芬克尔根据泥板和棋盘的构造，复原出一种两人比赛走子的玩法。","这一复原规则如今在世界各地流行。当然，乌尔的王族是否完全这样玩，无从得知。不过，在印度南部的科钦，直到20世纪50年代仍有人玩类似的游戏，让人感受到它漫长的生命。"],"quiz":[["提供玩法线索的泥板大约写于什么时候？","公元前2世纪（比棋盘晚两千多年）","与棋盘同时，约公元前2600年","中世纪（12世纪）","19世纪"],["是谁解读泥板并复原了玩法？","欧文・芬克尔","霍华德・卡特","商博良","亚瑟・伊文思"],["泥板上写的，停在格子上时是什么？","吉凶（运势）","国王的名字","税额","只有星星的名字"]],"kf":["棋盘约属公元前2600—前2400年，出自伊拉克南部乌尔的王陵","玩法是根据晚了两千多年的泥板复原的","20个格子，每方7枚棋子，用四面体骰子"],"more":[{"h":"王陵与“王家游戏”","p":["伍利在乌尔王陵找到的20格棋盘不止一块。最有名的一块（大英博物馆藏）是在木板上镶嵌贝壳、红色石灰岩和青金石，“王家游戏”这个名字就由此而来。","但这并不是王族专属的游戏。同样的20格棋盘从美索不达米亚到埃及、东地中海都有发现；在亚述宫殿里，守门的巨大人首翼牛像底座上，甚至还刻着一块大概是卫兵刻下的棋盘。"],"cap":["大英博物馆藏的“乌尔王家游戏”，可在馆藏展厅里以3D旋转观看"]},{"h":"棋盘的构造","p":["20个格子由3×4的12格和3×2的6格组成，中间用2格宽的狭窄“桥”连接。有5个格子画着花纹（玫瑰花饰）；按复原规则，落在这里可以再掷一次，而且是不会被吃掉的安全格。","骰子是四面体，4个角中有2个做了记号。一次掷4枚，记号朝上几个就走几步，所以点数是0到4。最常出现的是2（16次中6次），0和4各只有16次中1次。可以在博物馆的“偶然的道具”里亲手掷掷看。"],"cap":["20个格子与5个玫瑰花饰。绿色数字是一方棋子前进的顺序（复原规则）","掷4枚四面体骰子时各点数出现的次数（16种情况中）"]},{"h":"泥板说了什么","p":["泥板正面写着玩法，背面画着棋盘，格子里写有星座符号。落在格子上时的话语像占卜一样，例如“会遇到朋友”“会喝到上等啤酒”，可见这种游戏与运势相连。","不过泥板有残缺，并不是每条规则都能读出。芬克尔的复原是根据能读的部分和棋盘的形状，拼出最合理的玩法；学者之间也有别的复原方案。"]},{"h":"最后的玩家在印度","p":["芬克尔后来得知，住在印度南部科钦（柯枝）的犹太人社群，直到不久之前还在玩一种20格的游戏，棋盘形状也很相似。","在他们于20世纪50年代迁往以色列之前，这种游戏一直在家中传承。它也许是沿着古代商路传到印度，延续了四千多年。"]}],"tl":[["约前2600—前2400年","20格棋盘被放入乌尔王陵"],["前8世纪","亚述宫殿守门像的底座上刻下棋盘"],["前177/前176年","巴比伦书吏抄写记有玩法的泥板"],["1922—1934年","伍利发掘乌尔，找到棋盘"],["20世纪80年代初","芬克尔解读泥板，复原玩法"],["直到20世纪50年代","印度南部科钦还在玩非常相似的游戏"]]},"liubo":{"title":"六博为何消失了","lead":"汉代上至皇帝、下至百姓都为之着迷的游戏，几百年间连玩法都被遗忘了。","s":["六博是汉代（公元前206—公元220年）风靡中国的游戏。随葬俑、画像石乃至铜镜纹样上都留有它的身影，仙人博弈的画面也很常见。","汉朝灭亡后，六博迅速衰落，一般认为到唐代时玩法已经失传。消失的原因尚不清楚，有一种看法认为人们转向了围棋等其他游戏。","留下来的是棋盘和用具。棋盘上刻有由T、L、V形组合成的独特线条，一般认为是投掷细棍（箸）来决定行棋的步数。同样的纹样也见于所谓的“博局纹镜（TLV镜）”。","文字方面的线索也在逐渐积累。1993年，江苏尹湾汉墓出土了利用博局图进行占卜的文书。21世纪10年代发掘的海昏侯刘贺墓中，发现了一千多枚与六博有关的竹简，研究仍在进行中。","本图鉴中的“六博”是依据这些线索做出的复原版。不同学者的复原各有差异，真正的规则至今尚未完全明了——新的发现也许会改变它的玩法。"],"quiz":[["六博在中国哪个朝代最为流行？","汉","明","清","宋"],["一千多枚与六博有关的竹简是在哪里发现的？","海昏侯刘贺墓","秦始皇陵","敦煌石窟","紫禁城"],["一般认为六博投掷什么来决定步数？","细棍（箸）","二十面骰子","陀螺","画牌"]],"kf":["从战国到汉代（前5世纪—3世纪），在中国极为流行","棋盘刻着T、L、V组合的独特线条，掷细棍决定步数","汉亡后迅速衰落，玩法至今仍未完全弄清"],"more":[{"h":"T、L、V的棋盘","p":["六博棋盘是正方形，中央有方框，各边中间有T，周围有L，四角有V形的线。人们认为棋子就在这些线上或线间行进。","同样的线条也见于铜镜背面（规矩镜）和日晷。有学者认为棋盘是象征天地四方的宇宙图，可见六博不只是消遣。"],"cap":["六博棋盘的线条（TLV纹）：中央方框、各边的T、角上的L与V"]},{"h":"怎么玩","p":["多数学者认为双方各有6枚棋子，掷细竹棍（箸）决定步数。“六博”的“六”据说来自这6根棍或6枚棋子。","棋子前进后似乎会变成强大的“枭”。约公元前3世纪的《楚辞·招魂》中有“成枭而牟，呼五白些”一句。文献还记载了在棋盘中央的“水”里取“鱼”的玩法。"],"cap":["汉墓随葬的对弈六博的两人俑（大都会艺术博物馆）"]},{"h":"墓中出土的器具","p":["湖南长沙马王堆汉墓3号墓（约前168年）出土了装在漆盒里的棋盘、棋子和棍，一应俱全，是为了让墓主在另一个世界也能玩。","墓壁和石刻的画像石上，常描绘仙人在山上对弈六博的场面。六博也是与长生不老的仙界相连的特别游戏。"],"cap":["馆藏的六博棋盘，可在馆藏展厅以3D观看"]}],"tl":[["前5—前3世纪（战国）","六博棋盘开始被放入墓中"],["约前3世纪","《楚辞·招魂》吟咏六博对弈"],["约前168年","马王堆汉墓3号墓放入棋盘、棋子、棍一套"],["前206—220年（汉）","上至皇帝下至百姓都热衷，见于画像石与铜镜"],["唐（7—10世纪）","玩法被认为已经失传"],["1993年","尹湾汉墓出土用棋盘图占卜的文书"],["2010年代","海昏侯刘贺墓出土六博竹简"]]},"zeno":{"title":"芝诺皇帝的倒霉一掷","lead":"一千五百年前，一位皇帝掷出的骰子点数，化作诗句流传至今。","s":["罗马人喜爱“塔布拉”：在有24个点的棋盘上掷骰走子，是今天双陆棋（西洋双陆）的祖先。为了防止作弊，人们甚至使用让骰子从内部滚落的“掷骰塔”。","公元480年前后，东罗马皇帝芝诺正在下塔布拉。他掷出的三颗骰子是2、5、6。按规则他别无选择，只能这样走，结果棋盘上出现了八个孤零零、毫无保护的棋子。","记下这一局的是阿加提阿斯，一位生活在芝诺之后数十年、6世纪的历史学家兼诗人。他的短诗（隽语诗）连棋子的位置都写得很清楚，成了了解古代棋局的珍贵记录。","19世纪，法国学者贝克・德・富基埃尔根据这首诗解读出了棋局和规则：每人15枚棋子，骰子3颗；所有棋子都从棋盘外开始，双方朝同一方向前进。","与今天的双陆棋相比，塔布拉用三颗骰子，开局时棋盘上没有棋子，也没有加倍骰。多亏了皇帝的坏运气，我们才得以一窥塔布拉的样貌。"],"quiz":[["芝诺掷出的点数是？","2、5、6","6、6、6","1、1、1","3、4、5"],["是谁用诗记下了这一局？","阿加提阿斯","荷马","普林尼","西塞罗"],["下列哪项是塔布拉与今天双陆棋的区别？","塔布拉用三颗骰子","每人30枚棋子","棋盘只有12个点","棋子倒着走"]],"kf":["塔布拉用24个点和3颗骰子来玩，是双陆的祖先","约公元480年皇帝芝诺的一局，连同棋盘局面一起留在诗里","罗马人甚至造出防作弊的“骰塔”"],"more":[{"h":"塔布拉的棋盘","p":["塔布拉的棋盘和今天的双陆一样，把24个点分成两排，每排12个。每人15枚棋子，开始时全在盘外，按3颗骰子的点数入盘，绕一圈后再移出。","与双陆最大的不同，是双方都朝同一方向走。单独立着的棋子若被对方停上就会被吃掉，必须重新入盘。芝诺盘上那8枚，正是这种容易被吃的棋子。"],"cap":["塔布拉棋盘：24个点分成两排各12个，双方棋子都朝同一方向（箭头）前进"]},{"h":"防作弊的器具","p":["罗马人热衷掷骰，据说法律禁止赌博，只有冬季的农神节期间才被允许。但赌博从未停止，用手法操控骰子的作弊也很常见。","于是有了“骰塔”：从上面投入的骰子撞上塔内的板子后滚出。在德国一处别墅遗址发现的4世纪骰塔上，镂刻着“皮克特人已败，敌人已灭，安心玩吧”。"],"cap":["韦特魏斯—弗罗伊茨海姆的骰塔（4世纪），可在馆藏展厅以3D观看"]},{"h":"皇帝与骰子","p":["不只芝诺。史家苏维托尼乌斯记载，1世纪的皇帝克劳狄乌斯酷爱掷骰，还写过一本论掷骰技巧的书，并在马车里设法固定棋盘，好在途中也能玩。","罗马遗址还出土了许多由36个字母、每6个一组排成的棋盘；每个字母就是一格，有的刻着“起来，不会玩就让位”之类的调侃话。"],"cap":["塔布拉和掷骰是从皇帝到士兵的共同乐趣（可在“偶然的道具”展厅掷立方体骰子）"]}],"tl":[["1世纪","克劳狄乌斯皇帝写下掷骰之书"],["4世纪","德国的别墅里使用骰塔"],["约480年","东罗马皇帝芝诺不走运的一局"],["6世纪","阿加提阿斯把这一局写成诗"],["约10世纪","诗被收入《希腊诗选》流传下来"],["1869年","贝克·德·富基耶尔解读出局面与规则"],["1934年","奥斯汀详细重新检验芝诺的一局"]]},"sugoroku":{"title":"被禁止的双六","lead":"天皇下令禁止，人们却照玩不误。从古代到江户时代的日本盘双六的故事。","s":["正仓院保存着一件相传为圣武天皇喜爱的“木画紫檀双六局”。这里的双六不是纸上的绘双六，而是在棋盘上移动黑白棋子的“盘双六”，属于双陆棋一类。","双六很早就与赌博联系在一起。据《日本书纪》记载，689年持统天皇下令禁止双六。","757年施行的《养老律令》中，也有禁止僧尼玩双六的规定。禁令一再颁布，说明它们并没有被遵守。","到了平安时代，双六依然流行，《枕草子》和《源氏物语》中都有出现。《平家物语》记载，白河法皇曾举出三件不能如意的事：贺茂川的水、双六的骰子和比叡山的僧兵。","江户时代的版画中，仍可见少女们在室内玩盘双六。但到了明治时期，盘双六几乎无人再玩，“双六”一词转而指纸上的绘双六。"],"quiz":[["像正仓院双六局那样的“盘双六”属于今天哪种游戏一类？","双陆棋","将棋","围棋","扑克牌"],["据《日本书纪》，689年禁止双六的是哪位天皇？","持统天皇","圣武天皇","桓武天皇","明治天皇"],["白河法皇说不能如意的，除了贺茂川的水和僧兵，还有什么？","双六的骰子","将棋的棋子","围棋的棋子","蹴鞠的球"]],"kf":["盘双六是双陆的同类，7世纪时已在日本流行","以持统天皇689年的禁令为首，因赌博屡遭禁止","明治时期渐渐无人再玩，“双六”变成指纸上的绘双六"],"more":[{"h":"正仓院的双六盘","p":["正仓院所藏的“木画紫檀双六局”，是在紫檀盘上细细镶嵌象牙和染色木材的华美棋盘。左右各12个、共24个点位，中间的隔栏上饰有花纹。","正仓院还留有许多玻璃和石头做的双六棋子（双六子）。盘双六用黑白各15枚棋子和2颗骰子，器具与今天的双陆十分相似，一般认为是波斯的纳尔德经中国传来的。"],"cap":["正仓院的木画紫檀双六局，可在博物馆的馆藏展厅里对弈"]},{"h":"盘双六怎么玩","p":["双方各把15枚棋子按规定摆好，按2颗骰子的点数前进。黑白两方朝相反方向绕行，先把全部棋子集中到最后6个点位（内场）的一方获胜。","单独立着的棋子会被对方打回起点。叠了两枚以上的点位对方不能进入，所以诀窍是让棋子相连、封住道路。在博物馆的馆藏展厅里，可以用这种玩法在正仓院的棋盘上对局。"],"cap":["盘双六棋盘（示意图）：24个点位，黑白两方相向而行"]},{"h":"禁止与流行的反复","p":["持统天皇之后，双六又被禁止了许多次，因为沉迷赌博、倾家荡产的人始终不断。镰仓幕府也颁布过禁止以双六赌博的法令。","另一方面，双六也是贵族的修养。精美的双六盘被列为嫁妆，江户时代还制作了华丽的莳绘棋盘。作为赌具被厌恶，作为珍宝被喜爱——盘双六兼有这两副面孔。"],"cap":["江户时代画中的盘双六（描绘的游戏展厅）"]}],"tl":[["7世纪","盘双六从中国传入"],["689年","持统天皇禁止双六（《日本书纪》）"],["8世纪","木画紫檀双六局被收入正仓院"],["757年","《养老律令》施行，告诫僧尼勿玩双六"],["平安时代","双六出现在《枕草子》《源氏物语》中"],["12世纪","白河法皇感叹“双六的骰子”（《平家物语》）"],["江户时代","制作作为嫁妆的华美棋盘"],["明治","盘双六几乎无人再玩"]]},"queen":{"title":"国际象棋的王后为何成了最强的棋子","lead":"如今最强的棋子，原本只是一个只能斜走一格的臣子。","s":["国际象棋的祖先从印度传到波斯，又传入阿拉伯世界。波斯史诗《列王纪》中，有贤者布祖尔吉米赫尔解开印度送来的象棋之谜的情节。那时棋盘上站在王身旁的是“费尔兹（大臣）”。","费尔兹只能斜走一格，是很弱的棋子。在12世纪伊朗内沙布尔的棋具中，它是一个比王小的宝座形状。","国际象棋传入欧洲后，大臣变成了“王后”。12世纪的刘易斯岛棋子中也有王后。但名字虽然变了，走法依然很弱。","巨大的变化发生在15世纪末的西班牙。约1475年在巴伦西亚写成的诗作《爱的棋局》（Scachs d’amor），被认为是记载现代王后走法——横、竖、斜任意远——的最早记录。此后，卢塞纳（1497年）和达米亚诺（1512年）的书把新规则传遍了欧洲。","王后为何变强，至今没有定论。有人认为是为了让对局更快分出胜负，也有说法认为受到了伊莎贝拉一世等强势女王的影响。无论如何，这一变化让国际象棋大大接近了今天的样子。"],"quiz":[["在波斯和阿拉伯的象棋中，位于今天王后位置的棋子是？","费尔兹（大臣）","象","战车","马"],["最初的费尔兹怎么走？","斜走一格","直线任意远","跳两格","不能动"],["最早记载现代王后走法的诗写于哪里？","15世纪的巴伦西亚","6世纪的印度","12世纪的刘易斯岛","19世纪的伦敦"]],"kf":["皇后的前身是波斯、阿拉伯的“费尔兹（大臣）”，只能斜走一格","约1475年的西班牙，最早记录了今天强大皇后的走法","新规则借由印刷的书，在几十年内传遍欧洲"],"more":[{"h":"弱小的大臣","p":["费尔兹只能走斜向相邻的一格，和今天能从棋盘一端一口气冲到另一端的皇后大不相同。那时的国际象棋棋子走得很慢，一局下上好几个小时并不稀奇。","象（今天的主教）也只能斜跳到第二格。兵走到最后一排可以“升变”，但只能变成这个弱小的费尔兹。"],"cap":["费尔兹（左）与今天的皇后（右）能走的范围"]},{"h":"“皇后棋”与“疯狂棋”","p":["新皇后出现后，西班牙人把这种下法叫作“皇后棋”，意大利人则因其激烈称之为“疯狂棋”。差不多同时，主教也变得可以斜走任意格。","棋子变强后，对局一下子变得又快又激烈。研究几步就能取胜的陷阱、开局固定走法（定式）的书接连出现，国际象棋成了“需要钻研的游戏”。"],"cap":["利贝拉莱·达·维罗纳《下棋的人们》（约1475年），正是新皇后诞生时期的画"]},{"h":"为什么是皇后","p":["大臣为什么变成皇后，并不清楚。把站在王旁边的棋子看作王后，也许很自然。在拉丁语里，“费尔兹”变成“费尔西亚”，后来又被叫作“雷吉娜（皇后）”。","皇后变强的原因，除了想让对局更快分出胜负之外，也有人认为是因为那是卡斯蒂利亚的伊莎贝拉一世等强势女王的时代。历史学家玛丽莲·亚隆把这一变化与中世纪女性的地位联系起来讨论。"],"cap":["刘易斯岛棋子中的皇后（12世纪），走法仍然很弱"]}],"tl":[["约6世纪","印度诞生国际象棋的祖先恰图兰卡"],["7—9世纪","在波斯、阿拉伯流行，王旁边是费尔兹"],["约10世纪","国际象棋传入欧洲"],["12世纪","刘易斯岛棋子中出现皇后（走法仍弱）"],["约1475年","瓦伦西亚的诗《爱的棋局》记下新皇后的走法"],["1497年","卢塞纳的棋书在西班牙印行"],["1512年","达米亚诺的书在意大利出版，新规则传开"]]},"senet":{"title":"塞尼特为何成了通往冥界的旅程","lead":"在古埃及流传近三千年的游戏，后来象征着亡者灵魂的旅程。","s":["塞尼特是古埃及的一种游戏，在3行×10格的棋盘上移动棋子。约公元前3100年第一王朝的墓中，已发现疑似塞尼特棋盘的残片。王族用华丽的棋箱，百姓则在石头上刻出棋盘来玩。","它的名字意为“通过”。到了新王国时期（约公元前1550年起），塞尼特逐渐与亡者灵魂穿越冥界的旅程联系在一起。","《亡灵书》第17章描绘了亡者与看不见的对手下塞尼特的场面。拉美西斯二世的王后奈费尔塔利墓的壁画上，也有王后面对塞尼特棋盘的身影。","图坦卡蒙墓中至少出土了5个游戏箱。其中一个黑檀与象牙的大箱，正面是塞尼特，背面是另一种20格游戏的棋盘。","然而，至今没有发现完整记载玩法的文字。20世纪，热基耶、贝尔、肯德尔（1978年）等人根据棋盘、图画和文书残片，各自复原了玩法。本图鉴的塞尼特也是这类基于研究的玩法之一。"],"quiz":[["“塞尼特”这个名字的意思是？","通过","国王的游戏","三十间房","渡河"],["新王国时期，塞尼特与什么联系在一起？","亡者灵魂穿越冥界的旅程","求雨仪式","作战计划","丰收占卜"],["图坦卡蒙墓中至少出土了几个游戏箱？","5个","1个","2个","100个"]],"kf":["在3排×10格、共30格的棋盘上移动棋子，是世界上最古老的棋类之一","名字意为“经过”，新王国时期被看作灵魂穿越冥界的旅程","没有留下玩法记录，今天的规则是20世纪学者的复原"],"more":[{"h":"30格棋盘与特殊格","p":["塞尼特棋盘有3排，每排10格，共30格。一般认为棋子在第1排从左到右、第2排从右到左、第3排再从左到右，画出S形前进。","最后5格常画有特别的记号。第26格是“美丽之屋”，第27格是“水”，多数复原认为掉进水里的棋子要退回。第28到30格画着数字或冥界诸神。"],"cap":["塞尼特棋盘。棋子呈S形前进，最后5格（26—30）有特殊记号"]},{"h":"掷棍前进","p":["代替骰子的是4根一面平、一面圆的棍子，或动物的距骨。许多学者认为按平面朝上的根数前进，0根时走5步。","这种算法和遥远韩国掷柶的棍子完全一样。在博物馆的“偶然的道具”展厅掷投掷棒，就能看出1到5出现的难易差别。"],"cap":["埃及的投掷棒（可在“偶然的道具”展厅里掷）"]},{"h":"图坦卡蒙的游戏箱","p":["1922年霍华德·卡特打开的图坦卡蒙墓中，至少放着5个游戏箱。最大的一个用乌木和象牙制成，抽屉里可以收放棋子和投掷棒。","这个时期常做两面都是棋盘的箱子：一面是塞尼特，另一面是与乌尔王家游戏相同的20格棋盘。人们大概希望国王在另一个世界里两种游戏都能玩。"],"cap":["图坦卡蒙的塞尼特箱（可在馆藏展厅以3D观看并对弈）"]}],"tl":[["约前3100年","第1王朝墓中出土类似塞尼特的棋盘残片"],["约前2600年","古王国墓室壁画描绘下塞尼特的人"],["约前1550年起","新王国时期，塞尼特与冥界之旅相连"],["约前1323年","图坦卡蒙墓中放入5个游戏箱"],["约前1250年","奈菲尔塔利墓壁上画着面对塞尼特的王后"],["1922年","卡特打开图坦卡蒙墓"],["1978年","肯德尔发表玩法复原"]]},"lewis":{"title":"从沙中现身的棋子","lead":"1831年在苏格兰小岛上发现的中世纪棋子；188年后，又有一枚同一作坊的棋子从抽屉里现身。","s":["1831年，在苏格兰西北的刘易斯岛上，发现了一批主要用海象牙雕成的棋子：国际象棋棋子78枚、棋盘游戏用的圆片14枚、带扣1个，共93件。","发现的地点和经过并不清楚。通常说是岛西的乌伊格湾，但也有其他说法。是谁、为何把它们埋在那里，也不得而知。","一般认为这些棋子于12世纪后半叶在挪威特隆赫姆一带制作：国王、沉思的王后、主教、骑着矮壮小马的骑士，还有咬着盾牌边缘的守卫——被认为是北欧萨迦中的狂战士。","如今大英博物馆收藏82件，苏格兰国家博物馆收藏11件。人们一直认为，要凑成完整的几副棋还缺少一些棋子。","2019年，一位爱丁堡古董商在1964年仅花5英镑买下、家人一直收在抽屉里的守卫棋子，被认定出自刘易斯棋子的作坊，在苏富比拍卖会上以73.5万英镑成交。"],"quiz":[["刘易斯岛的棋子是哪一年发现的？","1831年","1066年","1931年","1700年"],["棋子主要用什么材料制成？","海象牙","大理石","黄金","玻璃"],["2019年拍卖的守卫棋子是哪一年以5英镑买下的？","1964年","1831年","1990年","2018年"]],"kf":["1831年在苏格兰刘易斯岛发现的93件棋子与圆盘","12世纪后半叶在挪威制作，主要用海象牙雕成","如今分别收藏在大英博物馆和苏格兰国家博物馆"],"more":[{"h":"78枚棋子的阵容","p":["78枚棋子包括王8、后8、主教16、骑士15、城堡卫士12、兵19，一般认为至少混有4副棋。","主教戴着主教冠。棋中的“象”变成“主教”是在欧洲发生的，刘易斯岛棋子是最早的例子之一。有几个卫士咬着盾牌，据说表现的是战前陷入狂暴的战士“狂战士”。"],"cap":["刘易斯岛棋子（可在馆藏展厅以3D观看）","78枚国际象棋棋子的构成"]},{"h":"海象牙与北方的海","p":["大多数棋子用海象牙、少数用鲸齿制成。海象牙是从格陵兰和挪威北部运来的北方海洋之宝。","当时刘易斯岛属于挪威国王统治的群岛，1266年依《珀斯条约》归苏格兰。特隆赫姆大教堂附近也发现过雕法相同的棋子残片，是棋子故乡的线索。"],"cap":[]},{"h":"发现的传说与今日的人气","p":["关于谁发现了棋子，流传着许多说法：有说是牛从沙里刨出来的，也有说是当地人马尔科姆·麦克劳德发现的。发现者很快卖掉棋子，经爱丁堡辗转，大英博物馆买下了大部分。","表情滑稽的棋子至今很受欢迎，复制品销往世界各地。电影《哈利·波特与魔法石》（2001年）里的巫师棋，也用了以刘易斯岛棋子为原型的棋子。"],"cap":[]}],"tl":[["12世纪后半叶","棋子在挪威（特隆赫姆一带）制成"],["1266年","依《珀斯条约》，包括刘易斯岛的群岛归苏格兰"],["1831年","在刘易斯岛一起发现93件"],["1831—32年","大英博物馆购入82件"],["1888年","苏格兰的博物馆取得11件"],["2001年","出现在电影《哈利·波特》的巫师棋中"],["2019年","当年5英镑买下的卫士以73.5万英镑拍出"]]},"tafl":{"title":"让国王逃脱的游戏与错误的翻译","lead":"维京人棋盘游戏的玩法，是从18世纪拉普兰的旅行日记中解读出来的。","s":["维京时代的北欧流行一种叫“塔夫尔”的棋盘游戏：棋盘中央的国王与少数护卫，同包围他们的大军作战，是一种双方兵力不对等的游戏。","1932年在爱尔兰巴林德里发现的10世纪木制棋盘，有7×7个孔，中央和四角的孔都做了标记，被认为是国王的起点和逃往的角落。","然而，记载中世纪玩法的文字几乎没有留下。重要线索是25岁的博物学家林奈于1732年在拉普兰（瑞典北部）旅行时写的日记，他在那里记下了萨米人玩的“塔布尔特”。","这部日记在1811年被译成英文出版，但译文有误。以此为基础的默里复原（1913年）长期成为塔夫尔的标准规则。","后来玩家和研究者纠正了这个错误，如今流行着多种版本的规则。本图鉴的塔夫尔也是其中之一。"],"quiz":[["林奈在拉普兰记下的游戏叫什么？","塔布尔特","塞尼特","播棋","国际象棋"],["守方要把哪颗棋子送到角落？","国王","王后","旗帜","船"],["有误的英译本是哪一年出版的？","1811年","1732年","1932年","1066年"]],"kf":["中央的国王和少数守卫，被人数更多的进攻方包围——双方兵力不对等的游戏","流行于维京时代的北欧，棋盘从7×7到19×19大小不一","玩法的线索来自林奈1732年的旅行日记，以及它有误的英译本"],"more":[{"h":"巴林德里棋盘","p":["巴林德里棋盘出土于爱尔兰中部湖上住所（克兰诺格）遗址，用紫杉木制成。7×7共49个孔，大概是把棋子底部的小柱插进去来下的。","棋盘边上雕着人头形状的把手，可见是一副便于携带的棋盘。爱尔兰文献里记有一种7×7的塔夫棋，名叫“布兰杜夫”（黑乌鸦），也许就是在这样的棋盘上下的。"],"cap":["在巴林德里棋盘（7×7）上摆出爱尔兰“布兰杜夫”的初始布局。金色圆圈标出中央和四角"]},{"h":"林奈记下的塔布尔特","p":["林奈记下的塔布尔特用9×9的棋盘。国王站在中央的王座上，守方8名“瑞典人”对阵攻方16名“莫斯科人”。","所有棋子都像车一样沿直线走任意格，被两个敌子前后或左右夹住就被吃掉。国王到达棋盘边缘则守方胜；从四面围住国王则攻方胜。林奈用拉丁语夹杂瑞典语写成，英译本里有几处与原文不同。"],"cap":["林奈记下的塔布尔特（9×9）：国王在中央王座，守卫8名，进攻方16名。国王走到绿色边缘格，守方获胜"]},{"h":"越来越大的棋盘，渐渐消失的游戏","p":["塔夫棋盘除了7×7，还有9×9、威尔士的11×11，甚至19×19。最大的“阿莱亚·埃万杰利”画在一部12世纪的抄本里，书中说它来自10世纪英格兰埃塞尔斯坦国王的宫廷。","12至13世纪国际象棋传遍北欧后，塔夫渐渐无人再玩，只有遥远的拉普兰保留了塔布尔特，碰巧被林奈记了下来。如今已有使用11×11棋盘的国际比赛，玩的人又多了起来。"],"cap":["刘易斯岛出土文物（12世纪）：与国际象棋棋子一起发现了14枚棋盘游戏用的圆片"]}],"tl":[["10世纪","爱尔兰制作巴林德里棋盘"],["924–939年","相传埃塞尔斯坦国王的宫廷里下阿莱亚·埃万杰利"],["12世纪","阿莱亚·埃万杰利的棋图被画进抄本"],["12–13世纪","国际象棋传遍北欧，塔夫逐渐消失"],["1732年","林奈在拉普兰记下塔布尔特"],["1811年","林奈日记的英译本《拉刻西斯·拉波尼卡》出版"],["1913年","默里在《国际象棋史》中复原塔夫"],["1932年","巴林德里棋盘出土"]]},"goose":{"title":"献给国王的鹅棋","lead":"掷骰子沿着63格螺旋前进的游戏，被献给国王，后来风靡整个欧洲。","s":["鹅棋是一种竞速游戏：掷骰子，沿着螺旋排列的63格走向中央的终点。停在画着鹅的格子上，可以按同样的点数再走一次；井、牢房和死神的格子则会让人停步或回到起点。","一般认为它诞生于16世纪的意大利。据说托斯卡纳大公弗朗切斯科一世·德·美第奇在1574年至1587年间，把这种游戏献给了西班牙国王腓力二世。","在英国，有1597年伦敦印刷商约翰·沃尔夫登记“新颖而有趣的鹅棋”的记录。17至18世纪，它在整个欧洲大为流行。","棋盘印在纸上传播，换了图案的版本多得数不清：学地理的、讲故事和寓言的，甚至还有做广告的。它被认为是后来许多竞速游戏的原型。","大都会艺术博物馆的一块双面棋盘，一面是鹅棋，另一面是国际象棋。一般认为它由16世纪后半叶印度古吉拉特的工匠制作，可能是现存最古老的鹅棋棋盘。"],"quiz":[["鹅棋有多少格？","63","64","100","30"],["据说是谁把鹅棋献给了西班牙国王？","弗朗切斯科一世·德·美第奇","拿破仑","伊丽莎白一世","路易十四"],["停在鹅的格子上会怎样？","按同样的点数再走一次","回到起点","休息一回合","与对手交换位置"]],"kf":["掷骰子沿着63格的螺旋走向中央终点的竞速游戏","16世纪诞生于意大利，相传由美第奇家族赠给西班牙国王","以印刷品的形式传开，换了题材的版本数不胜数"],"more":[{"h":"63格的螺旋","p":["在最常见的版本里，除了鹅格还有几个特殊格。停在6号“桥”上可以前进到12；19号“客栈”要停一回合；掉进31号“井”或52号“牢房”，要等别人过来解救才能动。","停在42号“迷宫”要退回30，停在58号“死神”就得从头再来。终点63必须正好掷到，多出的点数要往回走。最后一步往往最难。"],"cap":["把63格由外向内排成螺旋的图。绿色是鹅，蓝色是桥，黄色是受阻（客栈、井、牢房），红色是倒退（迷宫、死神），金色是终点"]},{"h":"9点的奥妙","p":["鹅格排在5、9、14、18……，间隔4格和5格交替。9的倍数格上总有鹅，所以掷9停在9上，就会一路跳到18、27……直达63。","因此用两颗骰子的版本有一条特别规则：第一次掷出6和3走到26，掷出5和4走到53。63等于7×9，据说当时人们把63岁看作一生中最危险的年龄，两者常被联系在一起。"],"cap":["鹅格隔4格、5格交替排列，9的倍数上总有鹅。第一次掷出9，就会从鹅跳到鹅，一口气到达63"]},{"h":"靠印刷传开","p":["棋盘用铜版和木版印刷，价格变得低廉。法国叫它“鹅棋”（jeu de l’oie），西班牙叫“juego de la oca”，西班牙至今还流传着“从鹅到鹅”的顺口溜。","换了图案的新版本层出不穷：学地理和历史的棋盘，以法国大革命或拿破仑为题材的棋盘，甚至还有商品广告的棋盘。同样的63格之上，画着每个时代关心的事。"],"cap":[]}],"tl":[["16世纪","被认为诞生于意大利"],["1574–87年","相传美第奇家族的弗朗切斯科一世把它送给西班牙国王腓力二世"],["16世纪后半","印度古吉拉特制作了正面鹅棋、背面国际象棋的双面棋盘"],["1597年","伦敦的约翰·沃尔夫登记出版"],["17–18世纪","风靡欧洲，题材各异的版本越来越多"],["1790年代","出现以法国大革命为题材的棋盘"],["19世纪","作为儿童游戏在各国大量印刷"]]},"shogi":{"title":"将棋的“持驹”是何时出现的","lead":"在国际象棋家族中，只有将棋能把吃掉的棋子当作自己的再打回棋盘。这条规则是何时、为何出现的？","s":["起源于印度的象棋祖先向东西方传播，在日本成了将棋。日本最古老的将棋棋子，是20世纪90年代初在奈良兴福寺旧址发掘出土的16枚。同时出土了写有“天喜六年（1058）”的木签，因此棋子也被认为是同一时期的东西。","当时的文献也提到了将棋。11世纪中叶写成的《新猿乐记》中出现了将棋之名；汇集平安时代末期记录的《二中历》，记载了使用玉将、金将、银将、桂马、香车、步兵的“平安将棋”。","镰仓、室町时代出现了许多增加棋子数量的大型将棋。成为今日将棋前身的“小将棋”中，除了飞车、角行，还有如今已不存在的“醉象”。","一般认为，持驹规则大约出现在16世纪。相传后奈良天皇下令从小将棋中去掉醉象，持驹也被认为是在那时开始的。","持驹为何出现尚无定论。有一种看法是：双方棋子颜色相同，只靠朝向区分敌我，所以吃掉的棋子容易直接使用。有了持驹，将棋直到终盘棋子都不会减少，也很少出现和棋。"],"quiz":[["与兴福寺棋子一起出土的木签上写的年份是？","天喜六年（1058）","大宝元年（701）","天正十年（1582）","明治元年（1868）"],["一般认为持驹规则出现在何时？","16世纪前后","8世纪前后","19世纪前后","20世纪以后"],["被认为让吃掉的棋子容易再用的原因是？","双方棋子同色，只靠朝向区分","棋子是金做的","棋盘格子很少","用骰子选棋子"]],"kf":["源于印度的象棋家族成员在日本成长而成，在9×9棋盘上对弈","最古老的棋子出土于兴福寺旧址，同时出土了天喜六年（1058）的木签","把吃掉的棋子当作己方棋子打入的“持驹”，被认为始于16世纪前后"],"more":[{"h":"同色的棋子，靠方向区分","p":["国际象棋的棋子分涂黑白两色，将棋的棋子却敌我都是同样的木色，靠五角形尖端朝哪边来区分。吃掉的棋子只要掉转方向就能打回盘上，靠的正是这种形状。","棋子上写着名字，进入敌阵后可以翻面“升变”。步翻过来是背面的“と”，走法和金将一样。棋子是写字的木片而不是立体的人偶，这一点与中国象棋、朝鲜象棋相同，是东亚象棋家族的特征。"],"cap":["将棋的棋子双方同色，靠尖端朝向区分。右边是翻面“升变”后的步（成金）"]},{"h":"大型将棋的时代","p":["从镰仓、室町时代到江户时代，人们造出了棋子种类和数量越来越多的大型将棋。12×12的中将棋直到江户时代都很流行，至今仍有爱好者。","记录里还有15×15的大将棋、25×25的泰将棋，以及在36×36棋盘上摆804枚棋子的大局将棋。不过平常下的是9×9的小将棋，它加上持驹规则，成了今天的将棋。"],"cap":["棋盘大小比较（左下角对齐）：9×9是现在的将棋（40枚），12×12是中将棋（92枚），15×15是大将棋（130枚），25×25是泰将棋（354枚），36×36是大局将棋（804枚）"]},{"h":"江户时代的将棋","p":["江户时代出现了领取幕府俸禄的将棋世家，大桥宗桂被视为第一代名人。每年在将军面前对局的“御城将棋”后来定在11月17日举行，今天的“将棋日”就由此而来。","将棋也是市井百姓的乐趣。春信的锦绘画着一对年轻男女在蚊帐旁下棋。还出现了像伊藤看寿《将棋图巧》（1755年）那样宛如艺术品的诘将棋作品集。"],"cap":["铃木春信的锦绘（约1767–69年）：在蚊帐旁下将棋的年轻男女"]}],"tl":[["1058年","兴福寺旧址的棋子（与天喜六年木签一同出土）"],["11世纪中叶","《新猿乐记》中出现将棋之名"],["镰仓时代初","《二中历》记下平安将棋的棋子"],["约16世纪","持驹规则被认为由此开始"],["1612年","相传大桥宗桂等人开始领取幕府俸禄"],["1716年","御城将棋定在11月17日举行"],["1755年","伊藤看寿《将棋图巧》"],["1975年","11月17日定为“将棋日”"]]},"pachisi":{"title":"帕奇西是怎样变成鲁多的","lead":"在印度宫廷里玩的十字形棋盘游戏，换了名字，走进了世界各地的儿童房。","s":["印度有乔帕尔和帕奇西等游戏，四个人在十字形棋盘四周移动棋子。乔帕尔掷细长的骰子（帕萨），帕奇西则掷宝贝壳来决定步数。“帕奇西”意为“25”，来自掷宝贝壳能得到的最大点数。","神话世界里也有人玩。17世纪末的一幅画中，湿婆神与妻子帕尔瓦蒂坐在虎皮上，围着乔帕尔的棋盘。","莫卧儿帝国阿克巴大帝（16世纪）的都城法塔赫布尔西格里，至今留有地面上画着巨大十字形棋盘的庭院。相传阿克巴让穿着彩衣的人充当棋子来下棋。","19世纪，这种游戏漂洋过海。在美国以“帕奇西”（Parcheesi）之名出售，1874年注册为商标。在英国，19世纪90年代以“鲁多”（拉丁语意为“我玩”）之名出售，成为家庭游戏。","鲁多规则更简单：只用一颗骰子，掷出6才能出棋。世界各地还有许多换了名字的同类游戏，如西班牙的“帕尔奇斯”、德国的“别生气”。"],"quiz":[["“帕奇西”这个名字的意思是？","25","王之路","十字","宝贝壳"],["留有巨大十字形棋盘庭院的阿克巴都城是？","法塔赫布尔西格里","德里的顾特卜塔","泰姬陵","埃洛拉"],["“鲁多”在拉丁语中是什么意思？","我玩","我赢","我跑","我掷"]],"kf":["在印度十字形棋盘上，四人两两结队、让棋子绕行一周的竞速游戏","名字意为“25”，来自掷宝贝壳时最大的点数","19世纪漂洋过海，以帕奇西（Parcheesi）、鲁多等名字传遍世界"],"more":[{"h":"十字棋盘与路线","p":["帕奇西的棋盘是从中央“查尔科尼”伸出四条臂的十字形。每条臂3列×8格，共96格。棋盘多是绣在布上的，不用时可以卷起来收好。","棋子从中央出发，沿自己那条臂的中列走下去，绕棋盘逆时针走一圈，再沿中列回到中央。对面的两人是同伴，两人的四枚棋子全部回家就获胜。"],"cap":["十字形棋盘（每条臂3列×8格）。蓝线是一名玩家的棋子路线：沿自己臂的中列走下去，逆时针绕一圈，再沿中列回到中央"]},{"h":"宝贝壳的算法","p":["帕奇西掷六枚宝贝壳，以开口朝上的个数决定步数。2到6枚朝上就走相应的步数；只有1枚朝上走10步，一枚都不朝上走25步。","25每64次才出现1次，是最罕见也最大的点数，游戏也因此得名。掷出6、10、25可以再掷一次。乔帕尔则是掷三根刻着1、2、5、6的长条骰子。"],"cap":["六枚宝贝壳中开口朝上的个数（上排）和可走的步数（下排）。柱高表示假设每枚贝壳正反面出现机会相同时的出现频率"]},{"h":"换个名字走向世界","p":["经由住在印度的英国人，这种游戏在19世纪传到欧美。在美国成为“帕奇西”（Parcheesi）商标，在英国“鲁多”于1896年取得专利，规则变简单，用一颗正方体骰子代替宝贝壳。","德国在1914年推出“别生气”（Mensch ärgere dich nicht），西班牙则流行“帕尔奇斯”（parchís）。各国的名字和细节虽有不同，绕十字棋盘一周回家的骨架始终不变。"],"cap":[]}],"tl":[["16世纪","阿克巴的法塔赫布尔西格里建起画着巨大十字棋盘的庭院"],["17–18世纪","印度细密画中常画围着乔帕尔的人们"],["1694–95年","德维达萨画下下乔帕尔的湿婆与帕尔瓦蒂"],["1874年","“帕奇西”在美国注册商标"],["1896年","“鲁多”在英国取得专利"],["1914年","“别生气”在德国发售"]]},"go":{"title":"1300年前的棋盘告诉我们什么","lead":"正仓院所藏的棋盘，有与今天相同的19路线，也有与今天不同的17个花形标记。","s":["围棋诞生于古代中国。传说是圣王尧为教导儿子而创。公元前的《孟子》中，就出现了围棋高手“弈秋”的名字。","一般认为棋盘的大小随时代而变化：早期也使用过17路的棋盘，后来今天的19路棋盘才普及开来。","围棋何时传入日本尚不清楚，但奈良时代已经有人下棋。规范僧尼的《僧尼令》禁止音乐与博戏，却唯独允许下棋和弹琴——与双六的待遇大不相同。","正仓院的“木画紫檀棋局”，是作为圣武天皇遗物流传下来的棋盘。盘面与今天一样是19路，但在星位处有17个花形标记（今天的棋盘只有9个星位）。两侧的抽屉连动，拉出一边，另一边也会出来。正仓院还藏有用染成红色和绀色的象牙雕刻鸟纹的棋子。","平安时代的《源氏物语》中有下围棋的场面。到了江户时代，本因坊家等家元为幕府效力，围棋成了职业棋手比拼技艺的技艺。"],"quiz":[["正仓院棋盘的盘面是几路？","19路","17路","13路","9路"],["《僧尼令》允许僧尼玩的是？","围棋和琴","双六","博戏","蹴鞠"],["正仓院棋盘上代替星位的花形标记有几个？","17","9","4","25"]],"kf":["在棋盘线的交叉点上落黑白棋子，比谁围住的地盘大——诞生于古代中国的游戏","棋盘经过17路的时代变成19路；正仓院保存着8世纪的19路棋盘","江户时代家元为幕府效力；21世纪AI战胜了人类第一人"],"more":[{"h":"围而提之，扩大地盘","p":["围棋由黑白双方轮流在棋盘线的交叉点上落子，落下的棋子不再移动。一颗棋子（或一块棋）相邻的空点全被对方棋子堵住时，就会被提走，从盘上拿掉。","最后比较各自围住的地盘加上提掉的子，多者为胜。规则虽少，棋盘却很大：19路棋盘上可能出现的局面数被算出约为10的170次方。"],"cap":["提子的方法。左：黑子旁边的空点（红色）有4个。中：被白子三面包围，只剩1个。右：最后一个也被堵住，黑子被提走"]},{"h":"从17路到19路","p":["河北望都的东汉墓中出土过17路的石制棋盘。另一方面，被认为约成书于6世纪的敦煌《棋经》写的是361个交叉点，也就是19路棋盘。棋盘大概是在这期间变大的。","正仓院的棋盘是19路，但不同于今天的9个星位，它在17处有花形标记。交叉点从289增加到361，棋就深奥了许多。"],"cap":["17路与19路棋盘的交叉点数比较。今天19路棋盘上的9个黑点是“星位”"]},{"h":"仙人的棋，家元的棋","p":["中国有“烂柯”的传说：樵夫在山中看仙人下棋，回过神来，斧柄都已朽烂，不知过了多少年。围棋作为仙人的游戏，常被画在盘子和画作上。","在日本江户时代，本因坊家等家元领取幕府俸禄，把围棋磨炼成一门技艺。1938年本因坊秀哉的引退棋，后来成为川端康成的小说《名人》。2016年，AI“阿尔法围棋”以4比1战胜世界顶尖棋手李世石，震惊世界。"],"cap":["雕着仙人对弈的漆盘（明宣德年间，1425–36年）"]}],"tl":[["约公元前4世纪","《孟子》提到围棋名手弈秋"],["东汉","望都墓中放入17路石棋盘"],["约6世纪","敦煌《棋经》记载19路、361个交叉点"],["8世纪","正仓院的“木画紫檀棋局”"],["1612年","相传本因坊算砂等人领取幕府俸禄"],["1938年","本因坊秀哉的引退棋，后成为川端康成《名人》"],["2016年","阿尔法围棋以4比1战胜李世石"]]},"draughts":{"title":"跳棋（国际跳棋）是怎样诞生的","lead":"阿拉伯的棋盘游戏、国际象棋的棋盘和国际象棋的王后——一般认为，三者相遇，诞生了国际跳棋。","s":["国际跳棋的祖先被认为是“阿尔奎克”，在用线连起的5×5个点上走棋。阿拉伯语称它为“基尔克”，10世纪的《诗歌集》中出现了它的名字。摩尔人把它带到西班牙，13世纪卡斯蒂利亚国王阿方索十世命人编写的《游戏之书》中记有玩法。","大约12世纪，可能是在法国南部，人们开始把阿尔奎克的棋子放到国际象棋棋盘上走，这就是“菲耶尔日”。棋子的名字与当时国际象棋的王后“费尔兹”相同。","棋子走到对方底线就变强的“升变”，在13世纪中叶的编年史中已有记载。也许是借鉴了国际象棋兵升为王后的规则。","重大变化发生在1535年前后的法国：加入了“能吃必须吃”的强制吃子规则，这种玩法被称为“强制游戏”。今天英美的跳棋就源自这一支。","另一方面，没有强制吃子的旧玩法作为“给女士的温和游戏”保留下来，后来发展为10×10棋盘的国际规则。同一个祖先，分出了好几种“王后的游戏”。"],"quiz":[["被认为是国际跳棋祖先的游戏是？","阿尔奎克","塞尼特","六博","播棋"],["“能吃必须吃”的强制吃子规则是何时何地加入的？","1535年前后的法国","10世纪的巴格达","1900年的美国","8世纪的日本"],["菲耶尔日的棋子与什么同名？","国际象棋的王后（费尔兹）","国际象棋的国王","骰子","骑士"]],"kf":["把阿拉伯游戏阿尔奎克的棋子搬到国际象棋棋盘上走，由此诞生的游戏","斜着走，跳过对方棋子吃子；走到底线就“升变”变强","约1535年加入“强制吃子”，2007年被完全算尽"],"more":[{"h":"从点与线的棋盘到国际象棋棋盘","p":["阿尔奎克的棋盘是用线连起的5×5共25个点。双方各摆12枚棋子，从空着的中央那一点开始走。棋子沿线移动，跳过相邻的对方棋子把它吃掉。","把这些棋子搬到国际象棋棋盘上时，只用一种颜色的格子。8×8棋盘的深色格有32个，双方各在靠自己的3行摆满，就正好是各12枚——和阿尔奎克一样。"],"cap":["阿尔奎克的棋盘和初始布局：5×5个点用横、竖、斜线相连，双方各摆12枚，只空出中央"]},{"h":"跳吃与升变","p":["棋子每次向斜前方走一格；相邻的对方棋子后面若是空格，就可以跳过去吃掉它。吃完还能再吃，就继续跳。能吃就必须吃，是今天跳棋的规则。","走到对方底线的棋子叠上第二枚，成为“王”，也能向后走。在10×10棋盘的国际规则里，王可以沿斜线走任意格，残局的打法因此大不相同。"],"cap":["跳棋的吃子与升变。红子连续跳过两枚白子吃掉（×），之后走到底线，叠上第二枚成为“王”"]},{"h":"被算尽的游戏，扩散的家族","p":["加拿大的乔纳森·谢弗等人做出了跳棋程序“奇努克”。1992年它与40多年几乎没输过的名手马里恩·廷斯利对战，廷斯利获胜。谢弗等人继续计算，2007年证明：双方都下出最佳着法时，跳棋是和棋。","另一方面，同一祖先的家族成员遍布世界：10×10的国际跳棋、俄罗斯的沙什基、横竖走的土耳其达马、12×12的加拿大跳棋等，在各国至今都有比赛。"],"cap":[]}],"tl":[["10世纪","《诗歌集》中出现基尔克（阿尔奎克）之名"],["约12世纪","菲耶尔日大概诞生于法国南部"],["1283年","阿方索十世的《游戏之书》记载阿尔奎克的玩法"],["约1535年","法国加入“强制吃子”"],["1547年","西班牙的托尔克马达出版第一本跳棋书"],["18世纪","10×10棋盘在法国和荷兰流行"],["1992年","廷斯利战胜程序“奇努克”"],["2007年","证明跳棋在最佳着法下为和棋"]]},"reversi":{"title":"黑白棋与奥赛罗，谁是发明者？","lead":"夹住并翻转黑白棋子的游戏。围绕它的发明，19世纪的英国有两个人争执不休。","s":["19世纪80年代的伦敦，两位英国人刘易斯·沃特曼和约翰·W·莫利特都声称自己才是这种游戏的发明者，并指责对方是骗子。","莫利特的游戏叫“兼并”，用的是十字形棋盘；沃特曼的“黑白棋”（Reversi）用普通的8×8棋盘。流传至今的是沃特曼的形式。围绕名称的争执还闹上了法庭。","黑白棋传遍欧洲，1893年德国的拉文斯堡公司把它作为最早的商品之一推出。在日本，明治时代的书里也有介绍，又被称为“源平棋”。","但它的热度并不长久。1971年，长谷川五郎推出了把最初四枚棋子在中央交叉摆放的“奥赛罗”，在日本大为流行。","据说名字取自莎士比亚的戏剧《奥赛罗》：黑皮肤的将军奥赛罗与白皮肤的妻子苔丝狄蒙娜，正对应黑白两色的棋子。今天比赛用的规则就是奥赛罗的形式。"],"quiz":[["争夺黑白棋发明权的两人是哪个时代、哪里的人？","19世纪的英国","18世纪的法国","20世纪的日本","16世纪的意大利"],["莫利特的“兼并”用的是什么形状的棋盘？","十字形","圆形","三角形","8×8的方形"],["1971年推出“奥赛罗”的是谁？","长谷川五郎","本因坊秀策","刘易斯·沃特曼","拉文斯堡公司"]],"kf":["用自己的棋子夹住对方棋子并翻面，最后棋子多的一方获胜","19世纪80年代的伦敦，两个英国人争夺发明者之名","20世纪70年代以“奥赛罗”之名在日本风靡，2023年被证明在最佳下法下为和棋"],"more":[{"h":"夹住就翻面","p":["只能在能用自己的棋子夹住对方棋子的格子落子。夹的方向有横、竖、斜共8个，一步可以同时夹住好几个方向。被夹住的棋子全部翻成自己的颜色。","没有可落的格子就弃权，双方都不能落子时游戏结束。四个角上的棋子永远不会被夹，所以占角非常有利。比起眼前的子数，减少对手能下的地方更重要。"],"cap":["落子与翻面。在红圈格落下黑子，横、竖、斜三个方向都夹住了白子，金边的7枚白子全部变黑"]},{"h":"最初的四枚棋子","p":["早期的黑白棋，由双方轮流把最初四枚棋子下在中央的四格里，所以既可能同色并排，也可能交叉。","奥赛罗规定最初四枚交叉摆放。一开始黑白双方都容易被夹，开局就是激烈的攻防。今天的世界大赛也从这个局面开始。"],"cap":["最初的四枚棋子。左：早期黑白棋的一种摆法（同色横向并排）。右：奥赛罗规定的交叉摆法"]},{"h":"人与电脑","p":["奥赛罗从日本传向世界，1977年在东京举办了第一届世界锦标赛。规则简单，胜负就看计算的深度，高手能算到几十步之后。","1997年，程序“Logistello”与世界冠军村上健下了6局，6局全胜。2023年，计算表明8×8的奥赛罗在双方都下出最佳着法时是和棋。"],"cap":[]}],"tl":[["1880年代","沃特曼与莫利特在伦敦争夺发明权"],["1893年","德国拉文斯堡公司推出黑白棋"],["明治时代","日本书籍以“源平棋”之名介绍"],["1973年","日本发售“奥赛罗”套装"],["1977年","东京举办第一届世界奥赛罗锦标赛"],["1997年","Logistello以6比0战胜世界冠军村上健"],["2023年","8×8奥赛罗被证明在最佳下法下为和棋"]]},"mancala":{"title":"播棋（曼卡拉）诞生在哪里","lead":"把石子像播种一样一个个分到坑里的游戏，在非洲和亚洲各地以数百种名字流传。","s":["“曼卡拉”是一类游戏的统称：从坑里取出石子或种子，一个个播撒到前面的坑里。据说这个词来自阿拉伯语“纳卡拉”（移动）。","各地的名字和玩法五花八门：西非的奥瓦雷、东非的巴奥、土耳其的曼加拉、东南亚的晨卡……多达数百种，有两排的也有四排的，坑数也各不相同。","人们常说它非常古老，但确切的证据却出乎意料地晚。目前年代明确的最古老棋盘，是古代阿克苏姆王国遗址（厄立特里亚的马塔拉、埃塞俄比亚的耶哈）出土的约6—7世纪的陶制和石制棋盘。","也有被认为更早的例子，但那些成排的孔是否真用于播棋还不清楚，学者意见不一。较有力的说法是，它从阿克苏姆传到阿拉伯和非洲内陆。","成体系的玩法记录要到17世纪前后才出现。在本图鉴的播棋中，可以用奥瓦雷、曼加拉等8种规则来玩。"],"quiz":[["“曼卡拉”一词所来自的阿拉伯语是什么意思？","移动","种子","坑","国王"],["年代明确的最古老播棋棋盘在哪里发现？","古代阿克苏姆王国遗址（埃塞俄比亚、厄立特里亚）","罗马斗兽场","中国长城","英国巨石阵"],["在西非流行的播棋是哪一种？","奥瓦雷","六博","塔夫尔","帕奇西"]],"kf":["从一个坑里取出全部棋子，从下一个坑起一颗一颗分下去的“播种”类游戏","年代确定的最古老棋盘，来自约6–7世纪的古代阿克苏姆王国","两排、四排、带“仓”的……各地棋盘与规则千差万别"],"more":[{"h":"播种","p":["播棋要从自己这边选一个坑，把里面的棋子全部取出，从下一个坑起一颗一颗放下去。这个像在田里撒种的动作叫“播种”。","西非的奥瓦雷开局有48颗棋子，12个坑各放4颗。最后一颗落入的对方坑若变成2颗或3颗，就可以把它们取走。分几颗、停在哪里，要靠往前数、往前算。奥瓦雷还越过大西洋，传到了加勒比海诸岛。"],"cap":["奥瓦雷的播种。把金圈坑里的3颗逆时针一颗颗分出去，最后一颗使对方的坑正好变成3颗，于是把这3颗取走（红圈）"]},{"h":"两排与四排","p":["播棋的棋盘大致分为两排和四排两类。西非和亚洲多是两排，四排的棋盘则从东非一直分布到非洲南部。坦桑尼亚的巴奥是4排×8坑，名字在斯瓦希里语里就是“棋盘”的意思。","像东南亚的晨卡、松卡那样，有的棋盘两端有存放所取棋子的大坑——“仓”。20世纪诞生于美国的“卡拉哈”也是带仓的两排形式；2000年，计算表明每坑4颗、6坑的卡拉哈先手必胜。"],"cap":["播棋棋盘的几种形状：2排×6坑（奥瓦雷等），2排×7坑加两端的仓（东南亚的晨卡等），4排×8坑（东非的巴奥等）"]},{"h":"把它记下来的人","p":["一般认为，最早详细记述播棋的欧洲学者是英国的托马斯·海德。他在1694年的《东方游戏考》中介绍了它的阿拉伯语名字和玩法。","1836年，爱德华·W·莱恩在描写开罗人生活的书中，记下了咖啡馆里玩的“曼卡拉”。如今研究者收集了各地的玩法，记录下来的规则多达数百种。"],"cap":[]}],"tl":[["6–7世纪","古代阿克苏姆王国遗址出土年代确定的最古老棋盘"],["1694年","托马斯·海德在《东方游戏考》中介绍播棋"],["18–19世纪","奥瓦雷等越过大西洋传到加勒比海诸岛"],["1836年","E·W·莱恩记下开罗的曼卡拉"],["20世纪中叶","带仓的两排播棋“卡拉哈”在美国发售"],["2000年","计算表明6坑4子的卡拉哈先手必胜"]]},"morris":{"title":"九子棋无处不在","lead":"神殿的屋顶、维京人的船、大教堂的石凳——凡是人们聚在一起的地方，都刻着这种棋盘的线。","s":["九子棋（直棋）是在三个套在一起的方框、共24个点上各放9枚子，连成三子“成磨”就能吃掉对方一子的游戏。英语名“莫里斯”与舞蹈无关，据说来自拉丁语 merellus，意思是“棋子、筹码”。","埃及库尔纳神庙屋顶石上刻的棋盘，常被说成约公元前1400年的最早实例。但学者贝格尔指出，同一处的刻画中混有科普特十字，认为“年代无法确定”。确切的例子始于罗马时代。","约公元900年的挪威戈克斯塔德船，甲板木板上刻着这种棋盘。在英国，坎特伯雷、索尔兹伯里等大教堂回廊的石凳上也留有棋盘。","1283年成书的阿方索十世《游戏之书》里，甚至画着用骰子来下的图。莎士比亚在《仲夏夜之梦》中写道，连日阴雨让“九子棋盘填满了泥”——说的是挖在村中草地上的棋盘。","1996年，德国的拉尔夫·加瑟用计算机查遍所有局面，证明双方都走最好时会和棋。即便如此，人与人对弈时它依然很有趣。"],"quiz":[["“莫里斯”这个名字据说来自？","拉丁语的“棋子”","英国的舞蹈","人名","船名"],["关于库尔纳神庙的棋盘，学者指出了什么？","年代无法确定","是用金子做的","来自中国","属于罗马皇帝"],["1996年用计算机证明了什么？","双方走最好会和棋","先手必胜","后手必胜","8枚子就够了"]],"kf":["在三个套在一起的方框共24个点上各放9枚子，连成三子就吃掉对方一子","从罗马时代起，船的甲板、大教堂的石凳等人群聚集之处都刻着棋盘","1996年电脑查遍所有局面，证明最佳下法下为和棋"],"more":[{"h":"落子、走子、飞子","p":["游戏分三个阶段。先由双方轮流把9枚子放到空点上；全部放完后，每次沿线把一枚子走到相邻的空点。","沿线把三枚子连成一行就“成磨”，可以从盘上拿掉对方一枚子。常见的规则是：子减到3枚时，可以“飞”到任何空点。子剩2枚或无路可走的一方输。"],"cap":["九子棋棋盘。白方在最外框的一边连成三子“成磨”（金色），可以吃掉一枚黑子（红叉）"]},{"h":"从三子到十二子","p":["这一族游戏以子数命名。每人3枚的三子棋棋盘很小，接近井字棋；每人6枚的六子棋用两层方框的棋盘。","每人12枚的十二子棋，是在九子棋棋盘上加了斜线。在南非叫“莫拉巴拉巴”，据说放牛的少年在地上画着玩，如今也有比赛。"],"cap":["棋盘比较。数字是每人的子数：三子棋、六子棋、九子棋、十二子棋的棋盘"]},{"h":"国际象棋名人与电脑","p":["国际象棋世界冠军埃马努埃尔·拉斯克也迷上了这种游戏。他在1931年的《各民族的棋类游戏》中，提出每人10枚、在落子阶段也能走子的新玩法。","1996年，瑞士的拉尔夫·加瑟把算尽所有残局的表格与从开局起的搜索结合起来，证明双方都下最佳着法时九子棋是和棋。棋盘只有24个点，局面数却多达数十亿。"],"cap":[]}],"tl":[["罗马时代","帝国各地的石头上刻着棋盘（可靠的古例）"],["900年前后","挪威戈克斯塔德船的甲板上刻着棋盘"],["1283年","阿方索十世的《游戏之书》画有九子棋"],["中世纪","英国大教堂回廊的石凳上刻着棋盘"],["1590年代","莎士比亚《仲夏夜之梦》写到被泥填满的棋盘"],["1931年","拉斯克在《各民族的棋类游戏》中提出新玩法"],["1996年","加瑟证明最佳下法下为和棋"]]},"patolli":{"title":"阿兹特克的豆子赛跑——帕托利","lead":"十字形的棋盘和打了孔的豆子骰子。赌得太凶，以致被西班牙人禁止的游戏。","s":["帕托利是墨西哥阿兹特克人玩的竞速游戏。名字的意思就是“豆子”：掷出5颗一面打孔或做记号的红豆，按朝上的记号数走棋。棋盘是画在席子或地上的十字形格子。","16世纪记录当地的迭戈·杜兰写道，玩家在掷之前会焚香、向豆子祈祷，并向游戏之神马奎尔索奇特尔祈求获胜。","贵族们押上宝石、衣服，有时甚至押上自己，输了就沦为奴隶。还流传着皇帝蒙特祖马观看贵族对局的故事。","西班牙修士厌恶赌博和对古老神祇的祈祷，于是禁止帕托利，毁掉棋盘、烧掉豆子，所以几乎没有器具留存。不过，刻在石地和岩石上的棋盘在特奥蒂瓦坎和玛雅遗址中被发现，1977年还在哈利斯科州的岩画中找到。","在十字形棋盘上绕圈走棋，这一点和印度的帕奇西非常像。1878年英国的泰勒主张它“从亚洲传来”，但现在一般认为两者是各自产生的。"],"quiz":[["帕托利用什么代替骰子？","做了记号的豆子","动物骨头","贝壳","木棍"],["记录中帕托利被禁止的理由是？","赌博和对古老神祇的祈祷","棋盘太大","豆子太贵","国王输了"],["和帕托利棋盘非常像的游戏是？","帕奇西","围棋","跳棋","播棋"]],"kf":["阿兹特克人掷带记号的豆子，在十字形棋盘上走子的竞速游戏","因与赌博和对神的祈祷相连，被西班牙修士禁止","与印度的帕奇西极为相似，但一般认为是各自独立诞生的"],"more":[{"h":"十字之路与52格","p":["帕托利的棋盘是画在布、席子或石地上的十字形道路。复原时多把四条臂各画成两列格子，加上中央4格，共52格。","52这个数恰好是阿兹特克历法循环一周的52年，因此有研究者把棋盘看作历法或时间流转的象征。玩家让棋子沿路绕一圈，先回来的获胜。"],"cap":["常见的帕托利棋盘复原：四条臂各有2列×6格的路，加上中央4格共52格。臂端的红格被认为是特殊格"]},{"h":"五颗豆子","p":["代替骰子掷出的是五颗一面钻了孔或做了记号的豆子，有几个记号朝上就走几格。五颗全是记号朝上，32次才会出现1次。","据说掷之前要对豆子说话，呼唤游戏之神马奎尔索奇特尔的名字祈祷。16世纪的《马利亚韦基亚诺抄本》画着人们在这位神的注视下围坐下帕托利。"],"cap":["五颗豆子中带记号的一面朝上的个数（0–5）及出现频率（每32次）。假设每颗豆子正反面出现机会相同"]},{"h":"与帕奇西极为相似","p":["棋子绕着十字形棋盘走，掷几样东西、按朝上的数前进——帕托利与印度的帕奇西、乔帕尔像得惊人。1878年，英国人类学家泰勒认为这不是巧合，而是从亚洲传来的证据。","但至今没有找到越过大洋传来的证据。如今一般认为，不同地方的人各自想到了同样的点子：绕圈的道路和用来掷的东西。"],"cap":["描绘印度乔帕尔的画（1694–95年）。棋子绕十字形棋盘行走的方式与帕托利非常相似"]}],"tl":[["特奥蒂瓦坎时代","石地上刻出十字形棋盘"],["1519–21年","西班牙征服阿兹特克"],["16世纪","《马利亚韦基亚诺抄本》画出帕托利与马奎尔索奇特尔"],["约1577年","萨阿贡在《佛罗伦萨抄本》中记下帕托利"],["约1581年","杜兰记下祈祷与赌博的情形"],["1878年","泰勒提出亚洲起源说"],["1977年","在哈利斯科州的岩画中发现棋盘"]]},"xiangqi":{"title":"象棋的河与炮","lead":"棋盘中间流过的“河”，和隔子吃子的“炮”。中国象棋是何时成为今天的样子的？","s":["象棋是在9×10条线的交点上下的中国棋。棋子是写着字的圆片，不像国际象棋那样走在格子里，而是走在线上。","早期的线索是唐代宰相牛僧孺（779–847）的志怪集《玄怪录》。书中有人梦见一支小小的军队，出现了天马、将、车、甲（步兵），还有像是炮的描写。不过棋盘和走法与今天并不相同。","9×10的棋盘、河与炮齐备的现代形式，出现在宋代（960–1279）的记载中。洛阳的北宋墓里还出土过一整套棋子。","河上常写着“楚河汉界”，据说源自公元前3世纪项羽的楚与刘邦的汉争夺天下时的分界。将不能走出“九宫”，两边的将也不能在中间无子时直接对面。","炮只有隔着一个子时才能吃子。象棋在越南也很受欢迎，叫“cờ tướng”；在朝鲜半岛则发展成了很相近的将棋（장기）。在大百科里，象棋和朝鲜将棋都能玩。"],"quiz":[["象棋的棋子走在哪里？","线的交点上","格子里","圆圈上","六角形格子里"],["现代形式的象棋出现在哪个朝代的记载中？","宋","汉","明","清"],["炮吃子的规则是？","隔一个子","直走一格","斜走两格","过河以后"]],"kf":["在9×10条线的交叉点上，用写着字的圆形棋子对战的中国象棋","棋盘中间有“河”，两边有将帅所在的“九宫”，每种棋子的活动范围各有规定","宋代定型，至今仍有数千万人在中国和越南下象棋"],"more":[{"h":"有河有宫的棋盘","p":["每方16枚棋子：将（帅）1、士（仕）2、象（相）2、马2、车2、炮（砲）2、卒（兵）5。同样职能的棋子，红黑两方的字有的稍有不同。","将和士不能走出九宫，象不能过河。卒过河前只能向前，过河后也能横走。马的前进方向紧挨着有棋子时就跳不过去（蹩马腿）。棋盘本身的结构决定了各个棋子的作用。"],"cap":["象棋的初始布局。上为黑方，下为红方。中间“楚河 汉界”是河界，上下画着斜线的3×3是九宫"]},{"h":"隔子打子的炮","p":["炮平时和车一样，横竖可以走任意格。但吃子时，中间必须正好隔一枚棋子（哪方的都可以），叫“炮架”，要跳过它才能吃。","如何利用炮架，形成了象棋独有的战术。开局把炮移到中路的“中炮”，至今仍是最受欢迎的开局之一。"],"cap":["炮的吃法：红炮隔着中间正好一枚黑马，吃掉远处的黑车"]},{"h":"棋谱与名手","p":["明代编出了许多收录名局和残局的书。1570年的《适情雅趣》和1632年的《橘中秘》至今仍是被研究的经典。","20世纪，胡荣华在全国赛中实现十连冠；1993年成立世界象棋联合会，跨国比赛开始举办。在中国和越南的公园里，今天也总有人围着棋盘看棋。"],"cap":[]}],"tl":[["9世纪","牛僧孺《玄怪录》中出现将、车、马等棋子"],["宋（960–1279年）","9×10棋盘、河界、炮齐备的现代形式出现在记载中"],["北宋","洛阳的墓中放入整套棋子"],["1570年","棋谱《适情雅趣》"],["1632年","棋谱《橘中秘》"],["1960–70年代","胡荣华全国赛十连冠"],["1993年","世界象棋联合会成立"]]},"backgammon":{"title":"双陆有5000年历史吗？","lead":"被称为“世界最古老的双陆”的棋盘，和它真正的祖先们——从波斯王宫到纽约的俱乐部。","s":["伊朗的“焚毁之城”沙赫里索赫塔出土了约5000年前的棋盘、60枚棋子和骰子，常被介绍为“世界最古老的双陆”。不过这块棋盘是用浮雕蛇身盘绕成约20个格子，形状与今天的双陆不同。","一般认为双陆的直接祖先是波斯的“纳尔德”，约在3到6世纪出现。7到9世纪写成的中古波斯语故事说，宰相博佐尔格梅赫尔解开了从印度送来的象棋之谜，作为回礼发明了纳尔德。","罗马也有用3颗骰子玩的棋盘游戏“塔布拉”（故事3里皇帝芝诺的那一局就是它）。这些“桌棋”类游戏传遍欧洲，衍生出法国的特里克特拉克等许多亲戚。","“双陆”的英文名 backgammon 出现在17世纪的英国；1743年，埃德蒙·霍伊尔把它的规则和战法写成了书。","最后一项大发明，据说是20世纪20年代纽约俱乐部里诞生的加倍骰。因为能在中途把赌注翻倍，双陆成了判断“何时出手”的深奥游戏。"],"quiz":[["沙赫里索赫塔的棋盘是什么形状？","蛇身盘绕成格子的棋盘","和今天的双陆一样","圆形的圆盘","十字形"],["故事里发明纳尔德的人是谁？","宰相博佐尔格梅赫尔","皇帝芝诺","埃德蒙·霍伊尔","阿方索十世"],["据说20世纪20年代在纽约诞生的是什么？","加倍骰","两颗骰子","24个三角形","15枚棋子"]],"kf":["在24个三角形上用两颗骰子推进15枚棋子，先把全部棋子移出棋盘的一方获胜","直接祖先是波斯的纳尔德和罗马的塔布拉等“桌棋”家族","加倍方块和电脑在20世纪为它增添了新的深度"],"more":[{"h":"15枚棋子与24个三角","p":["棋盘上有24个细长的三角形（点），双方各有15枚棋子。掷两颗骰子，按点数分别移动棋子，或让一枚棋子连走。掷出对子时，这个点数可以用四次。","落到对方单独的一枚棋子上，就能把它打到中间的“横杠”上，被打的棋子要从对方的内盘重新进入。15枚棋子全部进入自己的内盘后，开始把棋子移出棋盘，先移完的一方获胜。"],"cap":["双陆的初始布局。白方从24走向1（逆时针），右下的1–6是自己的内盘。黑方方向相反"]},{"h":"越近越容易被打","p":["能否打中对方单独的棋子，很大程度上取决于距离。相隔6点时，36种结果中有17种能打中；相隔7点时只剩6种。","记住这些数字，就知道棋子放在哪里危险。开局时，双方把所有棋子走完移出所需的点数总和都是167，高手会数这个“点数”来判断形势。"],"cap":["单独一枚棋子在1到12点外时，两颗骰子36种结果中能打中它的数目（途中没有阻挡时）"]},{"h":"从俱乐部到世界大赛","p":["1743年，英国的埃德蒙·霍伊尔出版了整理规则和战术的书。19世纪的英国人喜爱它到把它画在家具门上的程度；20世纪20年代，纽约的俱乐部里诞生了加倍方块。","1964年在巴哈马举办了世界大赛，20世纪70年代掀起热潮。1979年，汉斯·伯利纳的程序战胜世界冠军路易吉·维拉；1992年前后，通过自我对弈学习的“TD-Gammon”已接近人类顶尖高手的水平。"],"cap":["画着两位下双陆者的柜子（1861年，伦敦），莫里斯商会早期的家具"]}],"tl":[["约公元前3000年","沙赫里索赫塔埋入盘蛇形棋盘、棋子和骰子"],["约3–6世纪","波斯出现纳尔德"],["1743年","霍伊尔出版双陆之书"],["20世纪20年代","纽约诞生加倍方块"],["1964年","巴哈马举办世界大赛"],["1979年","伯利纳的程序战胜世界冠军"],["约1992年","自我对弈学习的TD-Gammon出现"]]},"hex":{"title":"被两位数学家分别发明的六贯棋","lead":"丹麦的诗人和美国的年轻天才，在互不知情的情况下想出了同一个游戏。","s":["六贯棋（Hex）是在排成菱形的六边形格子上轮流落子，谁先把属于自己颜色的两条对边连起来谁就赢，规则非常简单。","最早想到它的是丹麦数学家兼诗人皮特·海恩。1942年他在哥本哈根的尼尔斯·玻尔研究所介绍了这个游戏，同年12月26日以“多边形”（Polygon）之名登上《政治报》，并以50页一本的棋纸出售。","然而1943年海恩不得不离开丹麦，游戏也随之销声匿迹。几年后的1948至49年，美国普林斯顿大学的研究生约翰·纳什完全独立地想出了同一个游戏，据说同伴们把它叫作“纳什”。","1952年，派克兄弟公司以“Hex”之名发售；1957年马丁·加德纳在科学杂志的专栏里介绍了它，从此闻名世界。","六贯棋不会和棋。纳什还证明了“先手一定有必胜方法”，却没有给出具体走法。在大的棋盘上，那个赢法至今仍不清楚。"],"quiz":[["六贯棋怎样获胜？","连通自己颜色的两条边","吃光对方的子","包围王","连成五子"],["海恩的游戏登上丹麦报纸时叫什么？","多边形（Polygon）","纳什","Con-tac-tix","奥赛罗"],["纳什证明了什么？","先手有必胜方法","后手必胜","一定和棋","具体的必胜走法"]],"kf":["在六边形格子上轮流落子，把自己颜色相对的两条边连起来就获胜","1942年丹麦的海恩、1948–49年美国的纳什分别发明","没有和棋，先手必胜已被证明，但大棋盘上的胜法至今未知"],"more":[{"h":"只是连起来的游戏","p":["棋盘由菱形排列的六边形格子组成，正式大小是11×11。红方负责上下两边，蓝方负责左右两边，轮流每次落一子。落下的子不移动，也不会被吃。","棋盘下满时，一定有一方已经连通。六边形的格子不会只在角上相接，所以无法从对方的路线中间穿过去。1979年，数学家戴维·盖尔证明，这个“没有和棋”的性质与数学中著名的布劳威尔不动点定理等价。"],"cap":["7×7的六贯棋盘。红方连上下两边、蓝方连左右两边即胜。金边的红子已把上下连起来"]},{"h":"桥与梯","p":["高手常用的是“桥”。不紧挨着、而是隔一格落子，两子之间就有两个共同的空格。对方堵住一个，就下另一个，所以实际上已经连在一起了。","在棋盘边上，还有许多固定的棋形，例如像梯子一样沿边排子、最终连到边上的“梯”。由于先手优势太大，通常会采用“交换规则”：第一手之后，后手可以把先手那颗子算作自己的。"],"cap":["“桥”的形状。两枚红子可经由中间两个空格（虚线圆）中的任何一个相连。蓝方占了一个，红方就下另一个"]},{"h":"数学家的游戏","p":["纳什用“策略窃取”的思路证明了先手必胜：如果后手有必胜法，先手就可以把它偷过来用，这就矛盾了。这是一个不给出具体胜法的奇妙证明。","20世纪50年代，信息论之父克劳德·香农用电路做了一台会下六贯棋的机器。到了2010年代，9×9以下的棋盘已被电脑算尽，但11×11的正式棋盘至今仍未解开。"],"cap":[]}],"tl":[["1942年","海恩在丹麦报纸上发表“多边形”"],["1948–49年","普林斯顿的纳什想出同样的游戏"],["1952年","帕克兄弟公司以“六贯棋”之名发售"],["20世纪50年代","香农做出用电路下棋的机器"],["1957年","加德纳在科学杂志专栏中介绍"],["1979年","盖尔指出它与不动点定理的联系"],["2010年代","9×9以下的棋盘被电脑解开"]]},"foxgeese":{"title":"狐狸、鹅和国王的银棋子","lead":"一只狐狸对一群鹅。双方实力不对等的“狩猎游戏”的悠久历史。","s":["狐狸与鹅是一只狐狸跳过鹅把它吃掉，而鹅群设法把狐狸围得动弹不得的游戏，双方的规则完全不同。棋盘是用线连接33个点的十字形。","早期的线索是约14世纪写成的冰岛《格雷蒂尔萨迦》中出现的“哈拉塔夫尔”。意思是“尾巴棋盘”，一般认为尾巴指的是狐狸的尾巴。它大概是从北欧的塔夫尔分出来的游戏。","在英格兰，15世纪国王爱德华四世的账簿里，记着买了“镀金的银狐狸2只和猎犬26只”。这是两套的棋子，当时似乎叫作“狐狸与猎犬”。","原本的13只鹅让狐狸太占优势，后来增加鹅数的玩法流行开来。据说19世纪的维多利亚女王也很喜欢这个游戏。","同样的十字形棋盘也用于单人游戏孔明棋（单身贵族）。像尼泊尔的虎羊棋那样，老虎或狼追捕猎物的狩猎游戏遍布世界。在大百科里，狐狸与鹅和孔明棋都能玩。"],"quiz":[["哈拉塔夫尔中的“哈拉”是什么意思？","尾巴","狐狸","国王","雪"],["爱德华四世的账簿里记着什么棋子？","银狐狸和猎犬","金鹅","象牙国王","木骰子"],["使用同样十字形棋盘的单人游戏是？","孔明棋","数独","纸牌接龙","七巧板"]],"kf":["一只狐狸对13只（后来是17只）鹅，在33个点的十字形棋盘上对战","狐狸跳过鹅吃掉它；鹅把狐狸围得动弹不得就获胜","同样的棋盘也用于孔明棋，这类狩猎游戏遍布世界"],"more":[{"h":"一对十三","p":["狐狸沿线一步一步走，相邻的鹅后面若是空点，就跳过去吃掉它；像跳棋一样，有时还能连跳好几只。鹅不能吃子，在很多玩法里也不能后退。","鹅的目标是排得严丝合缝，把狐狸逼到走投无路。据说13只鹅时狐狸太占优势；改成17只鹅、不能后退的规则，下得好的话鹅就能赢。"],"cap":["狐狸与鹅的棋盘：33个点连成十字形。13只鹅排在上方；狐狸（橙色）跳过正前方的鹅（×），落到后面的空点，就能吃掉它"]},{"h":"狩猎游戏一家","p":["少数强棋追捕多数弱棋——这样的“狩猎游戏”遍布世界。尼泊尔的虎羊棋在5×5的棋盘上由4只虎追20只羊；2004年的计算表明，双方都下最佳着法时是和棋。","19世纪在德国流行的“阿萨尔托”用同样的十字形棋盘，由2名军官对24名士兵。这次是军官守城，士兵攻城。"],"cap":["狩猎游戏的数目比较：左边橙色是猎手，右边白色是猎物。从上到下：狐狸与鹅（1:13）、增加鹅的版本（1:17）、尼泊尔的虎羊棋（4:20）、阿萨尔托（2:24）"]},{"h":"从国王的棋子到孔明棋","p":["英格兰爱德华四世（1461–83年在位）的账簿里，记有购买镀金银质狐狸与猎犬棋子的记录。这也是王公贵族的消遣。","同样有33个孔的十字形棋盘，也用于单人玩的孔明棋。1697年的一幅法国版画上画着玩这种单人游戏的贵妇，被认为是孔明棋最古老的记录之一。"],"cap":[]}],"tl":[["约14世纪","冰岛《格雷蒂尔萨迦》中出现“哈拉塔夫尔”"],["15世纪后半","爱德华四世购买银质狐狸与猎犬棋子"],["1697年","法国版画画出玩孔明棋的贵妇"],["19世纪","相传维多利亚女王喜爱这种游戏"],["19世纪","同一棋盘的“阿萨尔托”在德国流行"],["2004年","尼泊尔虎羊棋被证明最佳下法下为和棋"]]},"latrunculi":{"title":"罗马士兵的棋盘","lead":"罗马人着迷的“佣兵游戏”。没有规则书留下来，线索是诗歌、逸事和从地下出土的棋盘。","s":["“拉特伦库利游戏”是古罗马的双人战斗游戏。“拉特伦库利”原指雇佣兵或强盗，棋子被看作士兵。","棋子在格子棋盘上移动，用自己的两枚棋子夹住对方的棋子就能吃掉它。1世纪的诗《皮索颂》描写了棋子前进、后退，以及被包围而动弹不得的情景。","哲学家塞涅卡讲过尤利乌斯·卡努斯的故事：他被皇帝卡利古拉判处死刑，百夫长来带他走时，他正在下拉特伦库利，还数了数棋子，对对手说“我死后可别说是你赢了”。","棋盘在罗马帝国各地都有发现。刻在军营和城镇石头上的格子，大小从8×8到12×12左右不等。英格兰斯坦韦的墓（1世纪）中，玻璃棋子还摆在棋盘上。","详细的规则书没有留下，今天的玩法是研究者的复原。大百科的拉特伦库利也是根据其中一种复原。"],"quiz":[["拉特伦库利怎样吃掉对方的棋子？","用两枚棋子夹住","跳过去","掷骰子决定","围住国王"],["处刑的人来时还在下拉特伦库利的是谁？","尤利乌斯·卡努斯","恺撒","尼禄","西塞罗"],["斯坦韦的墓里，棋盘上留着什么？","玻璃棋子","金币","国际象棋棋子","扑克牌"]],"kf":["古罗马的双人战斗游戏，棋子被看作士兵","用两枚棋子夹住对方就能吃掉；动不了的棋子也有记载","没有规则书，依据诗歌、逸事和出土棋盘复原"],"more":[{"h":"夹与围","p":["复原最详细的依据是1世纪的诗《皮索颂》。诗里像描写战场一样：一枚棋子上前引诱敌人，另一枚守住它的后方，被两枚敌子夹住的棋子就会失去。","诗中也提到被包围而动弹不得的棋子，所以许多复原除了夹吃之外，还为动不了的棋子定了规则。北欧的塔夫棋也有非常相似的夹吃方式。"],"cap":["拉特伦库利的吃法（复原）。左：按蓝色箭头走，用两枚黑子夹住白子即吃掉（×）。右：四面被堵住的白子不能动"]},{"h":"两面的棋盘","p":["诗人马提亚尔（1世纪）在为礼物写的诗中，咏唱了一块棋盘：一面按骰子点数走棋，另一面是两种颜色的士兵相互厮杀——一块板上同时有运气游戏和智力游戏。","用骰子的一面被认为是叫作“十二线”的竞速游戏，与后来的塔布拉和双陆是一家。博物馆藏品中的骰塔（皮尔古斯）也是罗马人用的器具。"],"cap":["马提亚尔所咏的两面棋盘示意：一面是掷骰子走十二条线的游戏，另一面是士兵游戏的格子"]},{"h":"从地下出土的棋盘","p":["罗马士兵在要塞的石头和地面上刻出格子来玩。在不列颠的哈德良长城附近，以及德国、西班牙和北非，都发现了刻出的棋盘。","斯坦韦的墓（1世纪中叶）里，木棋盘已经朽烂，但上面白色和蓝色的玻璃棋子还留在原位，像是下到一半。主人可能是一位医生，墓中还有医疗器具。"],"cap":["骰塔（皮尔古斯）。罗马人用这样的塔掷骰子以防作弊"]}],"tl":[["公元前1世纪","瓦罗记下拉特伦库利之名"],["公元前1世纪末","奥维德在爱情诗中提到这种游戏"],["1世纪","《皮索颂》用诗描写游戏"],["1世纪中叶","斯坦韦的墓中放入摆着棋子的棋盘"],["1世纪","塞涅卡讲述尤利乌斯·卡努斯的逸事"],["1世纪末","马提亚尔咏唱两面棋盘"],["1994年","舍德勒发表规则复原"]]},"amazons":{"title":"每走一步，棋盘就烧掉一格","lead":"1988年诞生于阿根廷的“亚马逊棋”，把国际象棋王后的走法和围棋的围地合在了一起。","s":["亚马逊棋是在10×10棋盘上、双方各用4个“亚马逊”的双人游戏，由阿根廷的瓦尔特·萨姆考斯卡斯于1988年发明。","一步由两个动作组成：先让亚马逊像国际象棋的王后一样沿横、竖、斜直线移动，再从落点用同样的走法射出一支箭。被箭射中的格子以后谁也不能通过。","每走一步棋盘就少一格，最后无法移动的一方输。没有和棋。","到了终盘，箭墙把棋盘分隔成好几个房间。这时只有自己能用的空格多的一方获胜，所以要像围棋数地那样判断形势。","光是第一步就有2000多种走法，对电脑来说也很难。数学家研究它，电脑比赛也把它列为项目。"],"quiz":[["亚马逊棋诞生在哪个国家？","阿根廷","巴西","西班牙","墨西哥"],["被箭射中的格子会怎样？","谁也不能再通过","下一手消失","变成对方的棋子","变成得分"],["亚马逊棋中输的是哪一方？","先无法移动的一方","先被吃子的一方","先围成地的一方","超时的一方"]],"kf":["1988年诞生于阿根廷、在10×10棋盘上的双人游戏","亚马逊像王后一样移动，再从落点射箭烧掉一格","无法移动的一方输；终盘像围棋一样数地"],"more":[{"h":"走，然后射","p":["只要不越过别的棋子或箭，亚马逊可以走任意格。然后从到达的格子，同样用王后的走法射箭——甚至可以射回刚离开的那一格。","这个游戏不吃子。取而代之的是，每走一步都封掉棋盘上的一格，堵住对方的去路。进攻和防守，都由同一支箭决定。"],"cap":["亚马逊棋的一步。白方亚马逊像王后一样移动（蓝），再从落点用同样走法射箭（红）。被箭射中的格子永远封住"]},{"h":"分成房间的棋盘","p":["随着对局进行，箭把棋盘隔成一个个房间。如果房间里只有一方的亚马逊，那里的空格就只属于这一方，每走一步用掉一格。","这时比的就是数格子：能用的格子多的一方能走得更久。这一点很适合数学中的“组合博弈论”，埃尔温·伯利坎普等人详细研究了亚马逊棋的终盘。"],"cap":["终盘示意。烧掉的格子组成的墙把棋盘分成四个房间：绿色只有白方能用，蓝色只有黑方能用。空格多的一方能走得更久"]},{"h":"生于杂志，在电脑间较量","p":["据说亚马逊棋最早刊登在阿根廷的一本谜题杂志上。规则简短，有国际象棋棋盘和棋子就能玩，于是借着互联网传遍了世界。","光第一步就有2000多种走法，开局像围棋一样考验对全局的感觉。2000年代起，它成为电脑比赛的项目，程序之间互相较量。"],"cap":[]}],"tl":[["1988年","瓦尔特·萨姆考斯卡斯发明亚马逊棋"],["20世纪90年代","借互联网传遍世界"],["2000年","伯利坎普发表终盘的数学研究"],["2000年代","成为电脑奥林匹克的比赛项目"]]},"loa":{"game":"行动线棋","title":"数多少，走多少","lead":"1969年在锡德·萨克森的书中问世的“行动线棋”。胜负不在吃子，而在谁先把自己的棋子连成一片。","s":["行动线棋（Lines of Action，LOA）是在8×8棋盘上、双方各用12枚棋子的双人游戏。由克劳德·苏西发明，1969年在游戏研究家锡德·萨克森的著作《A Gamut of Games》中介绍给世人。","棋子沿横、竖、斜直线前进。走几格，正好等于这条线上的棋子数（自己的和对方的都算）。每走一步，线上的数目就会变化，能走的距离也随之改变。","可以越过自己的棋子，但不能越过对方的棋子。落点上若有对方的棋子，就把它吃掉。","目标是让自己的所有棋子通过横、竖、斜的相邻连成一块。吃掉对方的棋子会让对方变少，有时反而帮对方更容易连起来——这是一个奇妙的游戏。","规则简短，却很难算深，因此常被用于游戏人工智能的研究。荷兰马斯特里赫特大学的程序曾多次在计算机比赛中夺冠。"],"quiz":[["决定棋子走几格的是什么？","这条线上的棋子数","骰子的点数","已经吃掉的棋子数","固定走3格"],["行动线棋怎样才算赢？","把自己的棋子全部连成一块","吃光对方的棋子","走到棋盘对面的边","吃掉对方的王"],["1969年在书中介绍行动线棋的是谁？","锡德·萨克森","马丁·加德纳","埃德蒙·霍伊尔","H·J·R·默里"]],"kf":["8×8棋盘、各12枚棋子的双人游戏；克劳德·苏西发明，1969年由锡德·萨克森的书介绍","棋子走的格数正好等于所在线上的棋子数；可越过己子，不能越过敌子","不比谁吃得多，而是谁先把全部棋子连成一块谁赢"],"more":[{"h":"先数，再走","p":["比如，经过某枚棋子的横线上有3枚棋子，这枚棋子就沿横向正好走3格，不能多也不能少。途中可以越过自己的棋子，但若有对方的棋子挡在中间，就不能朝那个方向走。","每枚棋子都在四条线上——横、竖和两条斜线——每条线的数目各不相同。一枚棋子一动，周围好几条线的数目都会变化，所以每走一步，盘上的“距离”都会重新洗牌。这种难以看透的感觉，正是行动线棋的魅力。"],"cap":["箭头起点的黑子可以去的地方。横线上有3枚棋子，所以走3格（越过己子没关系）；竖线上有2枚，所以走2格并吃掉白子。斜线上也是3枚，但途中有白子挡住，不能走（×）"]},{"h":"连成一块就赢","p":["连接按横、竖、斜的相邻来计算。只剩一枚棋子的一方也算“连成一块”，所以吃得太多，甚至会把胜利送给对方。","一步棋同时让双方都连成一块时怎么算，因版本和比赛而异。萨克森书的初版算和棋，后来的版本算走棋一方获胜，如今多数比赛算和棋。本大百科的行动线棋判走棋一方获胜。"],"cap":["获胜的局面。白子（金边）包括斜向在内彼此相邻，连成一块。黑子仍分成三块（虚线）"]},{"h":"计算机争夺的游戏","p":["行动线棋棋盘小、规则短，却变化深远，于是成了游戏人工智能研究的题材。马斯特里赫特大学的马克·维南兹编写的程序“MIA”在2003、2004、2006、2009年的计算机奥林匹克中夺冠，他的研究汇集在2004年的博士论文《Informed Search in Complex Games》中。","2008年，维南兹解开了缩小到6×6的行动线棋，证明双方都下出最佳着法时，先手（黑方）获胜。一般认为原本8×8的行动线棋至今尚未被解开。人类棋手的世界锦标赛也每年在智力运动奥林匹克（MSO）上举行。"],"cap":[]}],"tl":[["1960年前后","据说克劳德·苏西发明了行动线棋"],["1969","在锡德·萨克森的《A Gamut of Games》中被介绍"],["2003","维南兹的MIA在计算机奥林匹克夺冠（之后2004、2006、2009年再夺冠）"],["2004","维南兹发表博士论文《Informed Search in Complex Games》"],["2008","6×6行动线棋被解开，先手必胜"]]},"konane":{"title":"黑色熔岩与白色珊瑚的游戏","lead":"夏威夷人世代玩着的“科纳内”。它被写进了库克航海的记录，到了20世纪，数学家又用“组合博弈论”来研究它。","s":["科纳内是夏威夷原住民玩的双人游戏。棋盘上黑白棋子交替排满、不留空隙，双方跳过对方的棋子把它吃掉。","从前的棋子，黑的是熔岩，白的是珊瑚碎块。棋盘叫“帕帕穆”，是在一块平坦的大石头表面凿出小坑做成的。据说在夏威夷的创世颂歌《库姆利波》中也出现了这个游戏。","开局时，黑方先拿掉自己的一枚棋子，白方再拿掉相邻的一枚。由此空出的两个洞，就是跳吃的起点。","每一步都是“吃子”。棋子沿横或竖方向，跳过相邻的对方棋子，落在后面的空格上。只要是直线，就可以接连跳下去。","没有吃子可走的一方判负，没有和棋。这种简单的结构，后来引起了数学家的兴趣。"],"quiz":[["科纳内从前的白色棋子是用什么做的？","珊瑚","象牙","白色大理石","动物的骨头"],["科纳内中怎样算输？","没有吃子可走","棋子被全部吃光","先走到棋盘边缘","最后只剩一枚棋子"],["连续跳吃时，不允许做什么？","中途改变方向","一次吃掉两枚以上","中途停下","落在自己棋子旁边"]],"kf":["夏威夷原住民的双人游戏，开局时黑（熔岩）白（珊瑚）棋子交替排满棋盘","每一步都是沿横竖方向跳过对方棋子将其吃掉；走直线可以连跳","没有吃子可走的一方输；数学家用组合博弈论研究过它"],"more":[{"h":"跳过去，吃掉","p":["跳吃只能横向或竖向，不能斜跳。相邻对方棋子的后面若是空格，就跳过去落下，并把被跳过的棋子从盘上拿走。","落点处如果还能再跳，可以保持同一方向继续跳。但中途不能改变方向，也可以随时停下。每一步只能动一枚棋子。"],"cap":["白子在一步中向右连跳两次，吃掉两枚黑子（蓝色1、2）。落点处不能转向往下跳（×）"]},{"h":"最初的两个洞","p":["棋盘被棋子填满时，谁也跳不了。于是先手的黑方从中央4格或四角拿掉自己的一枚棋子，接着白方拿掉与这个洞横竖相邻的一枚自己的棋子。","这样并排的两个洞，就是最初的落点。洞开在哪里，会大大改变之后的走势。"],"cap":["两种开局方式。黑方从棋盘中央的4格（左）或四个角（右）拿掉自己的一枚棋子（1），白方再拿掉相邻的一枚（2）"]},{"h":"石盘与238个格子","p":["詹姆斯·库克第三次航海的记录（1784年出版的第三卷）写道，在夏威夷看到的石子游戏“很像我们的跳棋”，但更为复杂。执笔的是军官詹姆斯·金，他说棋盘长约2英尺，有238个格子，每行14个。","棋盘大小并无定规，流传下来的有6×7、9×13、13×20等各种尺寸。如今多在偶数的正方形棋盘上玩，本大百科可选6×6、8×8、10×10。夏威夷岛的普乌霍努阿-欧-霍瑙瑙国家历史公园里，至今仍留有刻在石头上的帕帕穆。"],"cap":["棋盘大小比较：库克航海记录中的14×17（238格）棋盘，以及本大百科可以玩的10×10、8×8、6×6"]},{"h":"被数学家发现的游戏","p":["“无法走棋的一方输”，而且到了终盘棋盘会分成好几个互不相干的部分——科纳内正适合用埃尔温·伯利坎普等人的“组合博弈论”来分析。迈克尔·恩斯特在1993年与伯利坎普合写了关于科纳内的短文，又在1995年的论文中求出了许多局面的值。","此后，又有爱丽丝·陈和爱丽丝·蔡研究只有一行的科纳内（2002年），以及鲍勃·赫恩证明棋盘越大、判断胜负就越极其困难（PSPACE完全）的研究。一个跳石子的游戏，也成了计算理论的题材。"],"cap":[]}],"tl":[["1778","库克的船队抵达夏威夷"],["1784","库克第三次航海的记录出版，载有金对石子游戏的描述"],["1993","恩斯特与伯利坎普合写关于科纳内的短文"],["1995","恩斯特的论文《Playing Konane Mathematically》"],["2002","陈与蔡总结一行科纳内的研究成果"]]},"peg":{"title":"诞生于宫廷的单人跳子谜题","lead":"17世纪末，路易十四的法国宫廷里流行着“孔明棋”（单人跳棋）。这个一颗颗减少棋子的简单谜题，也让数学家们着了迷。","s":["孔明棋是一个人玩的谜题。在棋盘的孔里插满棋子，只空出一个孔。","棋子沿横或竖方向跳过相邻的棋子，落到后面的空孔里。被跳过的棋子从盘上拿走。","目标是不断跳下去，最后只剩一颗棋子。若最后一颗正好留在正中央，就是完美结局。","可靠的记录来自17世纪末的法国、路易十四的宫廷。1697年的杂志《风雅信使》刊登了棋盘和规则，还有一幅版画描绘了身旁放着棋盘的贵妇人。","看似简单，其实很难。数学家莱布尼茨也对它感兴趣；到了20世纪，数学家们用给孔涂色的方法，说明了为什么有些题目根本无解。"],"quiz":[["被跳过的棋子会怎样？","从盘上拿走","变成对方的棋子","滑到旁边的孔里","下一回合再回来"],["英国式棋盘有多少个孔？","33","37","45","64"],["孔明棋最早的可靠记录来自哪里？","17世纪末路易十四的法国宫廷","古罗马的浴场","江户时代日本的寺子屋","19世纪美国的酒馆"]],"kf":["一个人玩的跳子谜题：跳过棋子把它拿走，最后剩一颗就成功","可靠记录始于1697年前后路易十四的法国宫廷；经典棋盘有英国式33孔和欧洲式37孔","把孔涂成三种颜色，就能事先看出哪些题目无解"],"more":[{"h":"跳过去，拿走","p":["只能横跳或竖跳，不能斜跳（三角形棋盘等带斜线的棋盘除外）。每跳一次就少一颗，所以从32颗开始，要跳31次才剩下最后一颗。","同一颗棋子可以连续跳好几次。把连跳算作一步的话，英国式棋盘“从中央到中央”最少18步就能解开。1912年欧内斯特·伯格霍尔特找到了这个解，1964年约翰·比斯利证明了不可能更短。"],"cap":["英国式棋盘的第一步。中央空着时，上方的棋子跳过下面一颗，落到中央（蓝色）；被跳过的棋子被拿走（×）"]},{"h":"源自宫廷的消遣","p":["孔明棋可靠的历史可以追溯到1697年前后路易十四的宫廷。那年8月的杂志《风雅信使》介绍了棋盘、规则和题目，版画家克洛德-奥古斯特·贝雷还刻画了身旁放着棋盘的苏比斯亲王夫人。","还有一个著名的说法：一位被关进巴士底狱的贵族为了解闷发明了这个谜题——但这只是无法证实的传说。据说法国用的37孔棋盘也在17世纪就有了，而去掉四角的33孔棋盘则被称为“英国式”。"],"cap":["两种经典棋盘：英国式33孔（左）和欧洲式37孔（右）。空着的孔是各自常用的起始孔"]},{"h":"涂上三种颜色就能看出","p":["把棋盘的孔沿斜线涂成三种颜色。这样，无论横竖，连续的三个孔一定是三种不同的颜色。跳一次，两种颜色各少一颗、另一种颜色多一颗，所以三种颜色棋子数的“奇偶”会同时翻转。","欧洲式棋盘空出中央时，三种颜色都是12颗，全是偶数。每跳一次只是在“全偶”和“全奇”之间切换，所以永远到不了“一种颜色1颗、另两种0颗”的最后一颗的局面。在这个棋盘上，从中央开始的题目是无解的。用同样的方法检查英国式棋盘，从中央开始时，最后一颗能留下的孔只有5个。"],"cap":["把欧洲式37孔棋盘按斜线涂成三种颜色。中央空着时，每种颜色都是12颗"]},{"h":"数学家的玩具","p":["据说莱布尼茨在1710年的笔记中写道，他喜欢倒着玩这个游戏——把跳过的孔重新填上。从终局倒推的思路，至今仍是解题的基本方法。","伯利坎普、康威和盖伊的《Winning Ways》（1982年）对这个谜题做了细致分析，并介绍了“宝塔函数”：给每个孔打分，使任何一跳都不会让总分增加，就能证明某些目标不可能达成。据说1999年还有人用计算机穷尽了所有局面。"],"cap":[]}],"tl":[["1697","在路易十四宫廷中流行，8月的《风雅信使》刊出棋盘与规则"],["1710","据说莱布尼茨写下倒着玩的方法"],["1912","伯格霍尔特找到英国式的18步解"],["1964","比斯利证明没有比18步更短的解"],["1982","《Winning Ways》整理了宝塔函数等分析"]]},"fanorona":{"title":"靠近吃子，离开也吃子","lead":"马达加斯加的国民游戏“法诺罗纳”。传说它曾决定过王位；进入21世纪，计算机证明了“双方都走最佳着法就是和棋”。","s":["法诺罗纳是马达加斯加广为流行的双人游戏。棋盘为9×5，画有横、竖、斜线，双方各用22枚棋子。","棋盘的样子就像把阿拉伯世界和欧洲流行的“阿尔凯尔凯”棋盘左右并排两块。一般认为，阿尔凯尔凯传到岛上后，发展成了独特的游戏。","最大的特色是吃子方式。无论是朝对方棋子“靠近”，还是从对方棋子“离开”，都能把这条线上连着的对方棋子一起吃掉。","能吃子时必须吃，吃了子的棋子还可以改变方向继续吃。一步棋就能让局面天翻地覆，这正是法诺罗纳的魅力。","传说有位王子因为下棋停不下来而错失了王位，可见它自古就深受喜爱。2007年，荷兰的研究者用计算机证明：双方都走最佳着法时，结果是和棋。"],"quiz":[["法诺罗纳的棋盘有多大？","9×5","8×8","7×7","6×6"],["法诺罗纳的两种吃子方法是？","“靠近”和“离开”","跳过和夹住","包围和撞击","掷骰和抽签"],["计算机证明双方最佳着法的结果是？","和棋","先手胜","后手胜","还什么都不知道"]],"kf":["马达加斯加的双人游戏：9×5棋盘上各摆22枚棋子，开局只空出正中央","朝对方棋子“靠近”或从对方棋子“离开”，就能把线上连着的棋子一起吃掉","2007年，计算机证明“双方最佳着法即为和棋”"],"more":[{"h":"靠近吃，离开也吃","p":["“靠近”时，棋子走一步后，若紧挨着的前方有对方棋子，就把它和同一条线上后面不间断连着的对方棋子全部吃掉。“离开”正好相反：吃掉起点紧后方的对方棋子，以及它后面连着的棋子。","一步就能吃掉好几枚，所以从开局起棋子就迅速减少。一步棋同时可以“靠近”和“离开”时，只能选择其中一种。"],"cap":["两种吃法。上：白子向右走一步靠近黑子，吃掉前方连着的3枚黑子（靠近）。下：白子向右走一步离开黑子，吃掉身后连着的2枚黑子（离开）"]},{"h":"两块阿尔凯尔凯并排的棋盘","p":["棋盘上有5×9＝45个点，除了横竖线，每隔一点还有斜线通过。棋子沿线一步一步走到相邻的点。开局时只有中央一点是空的，所以第一步一定是吃子。","这个棋盘就是两块5×5的阿尔凯尔凯棋盘拼在一起。阿尔凯尔凯是在10世纪的阿拉伯书籍中就已出现的古老游戏，一般认为法诺罗纳由它演变而来。它何时、如何传到岛上并不清楚，也有书说是17世纪前后。"],"cap":["开局的摆法：9×5的点上黑白各22枚，只空出正中央一点。虚线框是两块5×5的阿尔凯尔凯棋盘"]},{"h":"连续吃子的连锁","p":["吃了子的棋子可以继续吃。但每一步都必须换方向，也不能回到走过的点。要不要继续，由自己决定。","这样的连锁走得好，一步就能吃掉对方近一半的棋子。反过来，如果连锁停在不好的位置，马上就会被吃回去。"],"cap":["连吃的例子。白子（1）向右靠近吃2枚，（2）向上离开吃2枚，（3）向左靠近吃2枚。（1）之后不能继续向右（×）"]},{"h":"王位与计算机","p":["传说16世纪前后的伊梅里纳国王拉兰博装病，打算让最先赶回来的儿子继承王位。哥哥安德里安通波昆德林德拉正下着一盘难解的法诺罗纳，舍不得离开，结果弟弟安德里安贾卡当上了国王。还有一个说法：1895年法军入侵时，女王一方曾依赖仪式性的法诺罗纳对局。两者都无法证实。","2007年，荷兰马斯特里赫特大学的马尔滕·沙德等人算出了棋子在7枚以下的所有局面，并用证明数搜索证明了开局局面是和棋（论文于2008年发表）。据说计算在一台机器上花了一周以上。"],"cap":[]}],"tl":[["16世纪前后","拉兰博王的王位继承与法诺罗纳的传说"],["17世纪前后","认为法诺罗纳由阿尔凯尔凯演变而来的一种说法"],["1895","法国入侵时仪式性法诺罗纳对局的传说"],["2007","沙德等人用计算机证明是和棋"],["2008","论文《Best Play in Fanorona Leads to Draw》"]]},"janggi":{"title":"没有河的棋盘，只跳一次的炮","lead":"在韩国深受喜爱的“韩国将棋”（장기）。它使用和中国象棋相同的9×10棋盘，却去掉了河界，大幅改变了棋子的走法。","s":["韩国将棋是韩国自古流行的双人棋类游戏。一般认为它源自中国象棋，棋子放在9×10条线的交点上对战。","与象棋不同，棋盘中间没有“河”，象和兵都能走到棋盘任何地方。将（王）一开始就在“九宫”中央，不能走出九宫。","双方是楚（蓝、绿）和汉（红）。棋子是八角形，越强的棋子做得越大。楚先走。","开局前，双方各从4种摆法中选择马和象的位置。汉先摆，楚看过之后再决定，所以从摆棋时就开始斗智了。","除了将死，也可以用点数决定胜负。先手楚从72分开始，后手汉得到1.5分的“덤”（补贴），从73.5分开始，棋子被吃得越多，分数越低。"],"quiz":[["韩国将棋的棋盘上没有什么？","中间的河","九宫","九宫里的斜线","90个交点"],["炮移动时一定要做什么？","恰好跳过一枚棋子","站在对方棋子旁边","待在九宫里","没有被将军"],["按点数判定时，后手汉加多少分“덤”？","1.5分","0.5分","3分","6.5分"]],"kf":["源自象棋的韩国将棋：9×10的棋盘，但没有河","象走直一斜二的大步；炮必须恰好跳过一枚棋子才能走、才能吃","开局前从4种马象摆法中选一种；点数判定时后手汉有1.5分的덤"],"more":[{"h":"没有河的棋盘与4种摆法","p":["韩国将棋的棋盘和象棋一样是9×10个交点，但中间没有河。双方九宫里画有×形斜线，将和士在九宫内沿着这些斜线也能一步一步走。将一开始就放在九宫正中央。","摆法是把马和象互换位置得到的4种。汉先摆，楚看过之后再决定自己的摆法。象放在内侧还是外侧，会改变开局的进攻路线。"],"cap":["韩国将棋的棋盘与开局摆法。没有河，上下九宫里有斜线。虚线圈是马和象可以互换的位置；上方的汉和下方的楚选了不同的摆法"]},{"h":"马、象与被堵住的点","p":["马先横或竖走一步，再向外斜走一步。象走得更远：横或竖一步，再斜走两步。两者途中的点上若有棋子，都不能往那个方向走。","象棋的象不能过河，只能斜走两步；而韩国将棋的象腿长，能走遍整个棋盘。但相对地，它的路也很容易被堵住。"],"cap":["马（左）走直一斜一，象（右）走直一斜二。蓝点是能去的地方。途中的点上有棋子，就不能往那个方向走（×）"]},{"h":"只跳一次的炮","p":["炮无论走还是吃，都必须恰好跳过中间的一枚棋子。中间什么都没有就一步也走不了，所以开局时炮动不了。","被跳过的棋子和被吃的棋子都不能是炮，所以两门炮只能互相瞪眼，谁也奈何不了谁。比起不吃子时能自由走的象棋的炮，它脾气古怪得多。"],"cap":["炮的走法。上：恰好跳过一枚卒，可以走到后面的点，或吃掉车（蓝）。中：中间的棋子是炮就不能跳。下：炮不能吃炮（×）"]},{"h":"对面的将与点数","p":["两个将在中间无子的线上面对面，叫作“빅장”（bikjang）。按一种规定，被对面的一方若不解开，就是和棋。传统规则中，没有被将军时还可以停一手（pass）。","分值为车13、炮7、马5、象3、士3、兵2。楚合计72分，汉加上덤为73.5分。因为有0.5的零头，按点数判定永远不会同分。本大百科的韩国将棋在同一局面重复3次或达到200手时，就按这个点数决定胜负。"],"cap":[]}],"tl":[["高丽时期","有观点认为当时已经有人下（传入时间众说纷纭）"],["18世纪","据说有更大棋盘的变体“广象戏”的记载"],["1895","斯图尔特·库林的《Korean Games》刊出下韩国将棋的人们的插图"],["2009","据说首届国际比赛在中国哈尔滨举行"]]},"pic":{"tlvmirror":"规矩镜（东汉，克利夫兰艺术博物馆）","kotoboard":"琴棋书画图（江户时代，约1620—1650年，克利夫兰艺术博物馆）","homerbg":"温斯洛·霍默《双陆》（约1877年木口木刻，克利夫兰艺术博物馆）","trictrac":"菲利普斯·德·科宁克《下特里克特拉克的人》（约1660年素描，克利夫兰艺术博物馆）","gametable":"嵌有国际象棋盘和莫里斯棋盘的游戏桌（美因茨，约1735年，克利夫兰艺术博物馆）","kota":"科塔王公礼拜的神龛，台阶上放着十字形的乔帕尔棋布（约1825年，克利夫兰艺术博物馆）"},"mahjong":{"game":"麻将","title":"名字叫“麻雀”的牌戏","lead":"19世纪诞生于中国的麻将。纸牌游戏变成了骨牌，1920年代在美国风靡一时，在日本则发展成了立直麻将。","s":["麻将是4个人玩的牌类游戏。使用136张牌（加上花牌是144张），谁先凑成规定的牌型谁就和牌。","它诞生于19世纪的中国。源头是用画着钱币单位的纸牌来玩的“摸牌、打牌”游戏，一般认为纸牌在19世纪中叶前后变成了骨牌。","现存最古老的麻将牌约制于1870年，是在宁波、上海、福州得到的。有书说它诞生在宁波，也有书说它源于福建、广东渔民的游戏。","“麻雀”就是麻雀鸟。有一种说法认为，名字来自古老的纸牌游戏“马吊”。常听说的“孔子发明麻将”，则是毫无根据的俗说。","进入20世纪，麻将漂洋过海。它在1920年代的美国风靡一时；在日本，后来出现了“立直”规则，发展成了独特的麻将。"],"quiz":[["不算花牌时，麻将牌一共多少张？","136张","144张","108张","152张"],["和牌的基本牌型是？","4组面子加1对将","只有7组","13张相同的牌","3组加2对"],["1920年代麻将在哪个国家风靡一时？","美国","俄罗斯","巴西","埃及"]],"kf":["19世纪在中国由纸牌游戏演变而来的4人牌戏","万子、筒子、索子的数牌，加上风牌和三元牌；凑齐4组面子和1对将即和牌","1920年代在美国风靡一时；战后的日本发展出立直麻将"],"more":[{"h":"136张牌","p":["数牌有万子（字）、筒子（圆）、索子（竹）3种，各从1到9每种4张，共108张。再加上东、南、西、北风牌和白、发、中三元牌各4张，一共136张。","中国的许多玩法还使用梅、兰、菊、竹和春、夏、秋、冬8张花牌。花牌不计入牌型，摸到后放在一边，用来加分。日本麻将一般不用花牌。"],"cap":["麻将牌的种类。万子、筒子、索子的1到9，风牌（东南西北）和三元牌（白发中）各4张，共136张。加上虚线下面的8张花牌（各1张）就是144张"]},{"h":"4组面子与1对将","p":["手牌13张，一摸一打，反复进行。用摸到的牌或别人打出的牌凑成4组面子和1对将，就和牌了。","面子有3种：同花色连续3张的“顺子”、相同3张的“刻子”、相同4张的“杠子”。也可以吃、碰别人打出的牌来组成面子，要什么牌、打什么牌，是一场漫长的斗智。"],"cap":["和牌的基本牌型：顺子（同花色连续3张）、刻子（相同3张）、杠子（相同4张）共4组，加上1对将（相同2张）"]},{"h":"漂洋过海的麻将","p":["1920年，约瑟夫·帕克·巴布科克出版了英文规则书，纽约的商店也从中国进货出售麻将。麻将在1920年代的美国风靡一时，1937年成立的全美麻将联盟至今传承着美国独特的玩法。","麻将在1920年代传入日本，据说1924年平山三郎在东京开了麻将馆和教室；1929年以作家菊池宽为总裁成立了日本麻将联盟。战后的1952年，据说天野大三在报纸上发表了带“立直”的规则，日本独特的立直麻将由此普及。"],"cap":["麻将传播的路线：1920年代从中国传到美国和日本；日本在1952年出现立直规则，中国在1998年制定国家正式规则"]},{"h":"传说与真实的历史","p":["关于麻将的起源有许多传说。孔子发明麻将的说法毫无根据；宁波一位名叫陈鱼门的人发明麻将的故事，因为据说出处的文件从未找到，很可能也是编造的。","可以确定的是，19世纪中国用钱币纸牌玩的“摸打”游戏变成了骨牌游戏。早期的牌没有现在的花牌和发，取而代之的是“王”牌等。1998年，中国还制定了国家正式规则。"],"cap":[]}],"tl":[["19世纪中叶","纸牌游戏被认为变成了骨牌游戏"],["1870年前后","现存最古老的牌（宁波、上海、福州）"],["1920","巴布科克出版英文规则书"],["1929","日本麻将联盟成立"],["1952","带立直的“报知规则”发表"],["1998","中国制定国家正式规则"]],"figL":{"hand":["顺子","刻子","杠子","顺子","对子"],"spread":[["约1870","宁波・上海・福州","现存最古老的牌"],["1920","美国","巴布科克规则风靡"],["1920年代","日本","传入，1929年成立联盟"],["1952","日本","报纸刊出立直规则"],["1998","中国","国家正式规则（81番种）"]]}},"gomoku":{"title":"先手太强的五子棋","lead":"用围棋盘和棋子就能玩的“五子棋”。在日本自江户时代起深受喜爱，为了抑制先手的优势诞生了“连珠”规则，最后由计算机给出了答案。","s":["五子棋是用围棋盘和棋子玩的双人游戏。黑白交替落子，谁先在横、竖、斜任一方向连成5子谁就赢。","它的起源并不清楚。有说法认为可追溯到古代中国或日本平安时代，但可靠的记录出自日本江户时代，据说18世纪中叶已有人玩。","下得越多，人们越发现先走的黑方占优势。于是在日本，逐渐形成了只对黑方设“禁手”的规则。","1899年，《万朝报》的黑岩泪香给这个游戏取名“连珠”，意思是连成一串的珠子。","1988年，国际连珠联盟（RIF）在瑞典斯德哥尔摩成立，并举办世界锦标赛。另一方面，计算机证明了没有禁手的五子棋是先手必胜。"],"quiz":[["五子棋怎样获胜？","自己的棋子连成5个","围住对方的棋子吃掉","占领棋盘一半以上","吃掉对方5个棋子"],["给这个游戏取名“连珠”的是谁？","黑岩泪香","本因坊道策","夏目漱石","福泽谕吉"],["连珠中只禁止黑方的着法是？","三三、四四、长连","下在棋盘边上","下在白子旁边","包围对方的棋子"]],"kf":["用围棋盘和棋子玩、连成5子即胜的游戏；可靠记录始于日本江户时代","因为先手黑方占优，连珠对黑方设有三三、四四、长连禁手","1994年证明了无禁手的15×15五子棋先手必胜"],"more":[{"h":"连成5子，四三取胜","p":["决定胜负的是对手一步挡不住的“双重威胁”。再差1子就成5的“四”必须马上挡住，否则就输。两端开放的3子“三”若不理会，就会变成两端开放的四，再也挡不住。","一步同时形成四和三的“四三”一旦出现，白方只能先挡四，接着三延伸成活四，胜负就定了。五子棋的进步，在于能多早看出这个形。"],"cap":["左：斜向连成5子即胜。右：红圈这一手同时在横向形成“四”（下在4的点即成5），在竖向形成两端开放的“三”（3的点），白方无法两边都挡住（四三）"]},{"h":"只限黑方的禁手","p":["在连珠中，黑方不能下“三三”“四四”“长连（6子以上）”，下了就算犯规判负。白方没有禁手，连成6子以上也算赢。","黑方要赢，就必须做出像四三这样不犯禁的形。白方甚至可以故意把黑方逼进禁手，这种斗智让连珠更加深奥。"],"cap":["连珠中黑方的禁手（×）。从左起：同时形成两个三的“三三”、同时形成两个四的“四四”、连成6子以上的“长连”"]},{"h":"被解开的五子棋","p":["1994年，荷兰的维克托·阿利斯用计算机证明：在无禁手的15×15五子棋中，先手黑方一定能赢。2001年，瓦格纳和维拉格又证明了没有开局规定的连珠也是先手胜。","人们仍然在下，是因为取胜的路线复杂到人无法记住。比赛中使用决定开头几手下法的“开局规定”（如山口规则、Soosõrv-8），力求公平。"],"cap":["五子棋与连珠的历程：从江户时代的五子棋，到连珠的命名、国际联盟和计算机的证明"]},{"h":"遍及世界的五子连线","p":["19世纪，它以“Go Bang”的名字传到英国。如今世界各地都有类似的游戏：韩国的五目（오목）、越南的Caro，还有能成对吃子的Pente等。","本大百科的五子棋在15×15棋盘上进行，可以从连珠、标准、自由三种规则中选择。不妨比较一下，看看连珠的禁手把先手的优势压低了多少。"],"cap":[]}],"tl":[["18世纪中叶","据说日本江户时代已有人玩五子棋"],["1856","现存最早的五子棋书《五目定石集》"],["1899","黑岩泪香命名为“连珠”"],["1988","国际连珠联盟（RIF）在斯德哥尔摩成立"],["1994","阿利斯证明自由规则五子棋先手必胜"],["2001","瓦格纳和维拉格证明无开局规定的连珠先手胜"]],"figL":{"time":[["1700s","日本（江户）","已有人玩五子棋"],["1899","日本","命名为“连珠”"],["1988","斯德哥尔摩","国际连珠联盟成立"],["1994","荷兰","五子棋先手必胜"],["2001","匈牙利","连珠也是先手胜"]]}},"carrom":{"title":"用手指弹进袋里的克朗棋","lead":"在印度和南亚，家人和邻居聚在一起玩的“克朗棋”（卡罗姆）。用手指弹出棋子，把棋子打进棋盘四角的袋里，有点像台球。","s":["克朗棋在约74厘米见方的光滑棋盘上进行。四角各有一个洞（袋），2人对坐，或4人两两组队来玩。","棋子共19枚：白9枚、黑9枚和1枚红色的“皇后”。轮到自己时，把稍大稍重的“母棋”放在自己面前的线（底线）上，用手指弹去撞棋子。","把自己颜色的棋子全部打进袋就赢了。不过红色的皇后，打进之后必须接着再打进一枚自己的棋子来“掩护”，才算自己的。","一般认为它起源于印度，据说北印度帕蒂亚拉的宫殿里至今仍展出一块玻璃面的棋盘。20世纪初，印度已经举办过邦级比赛。","1988年，国际克朗棋联合会在印度金奈成立，1991年起举办世界锦标赛。类似的“弹击”游戏遍布世界，如加拿大的克罗基诺尔、拉脱维亚的诺乌斯等。"],"quiz":[["不算母棋，克朗棋有几枚棋子？","19枚","16枚","24枚","32枚"],["怎样才能让红色皇后归自己？","接着打进一枚自己的棋子（掩护）","最后才打进","第一击就打进","连续撞它两次"],["国际克朗棋联合会1988年在哪座城市成立？","金奈","伦敦","科伦坡","孟买"]],"kf":["四角有袋的棋盘上，用手指弹母棋把棋子打进袋的游戏","白9、黑9、红皇后1；皇后要接着打进自己的棋子来“掩护”","一般认为源于印度；1988年成立国际联合会，1991年起举办世锦赛"],"more":[{"h":"棋盘与19枚棋子","p":["棋盘四角有带网的袋，每边近处画着两条线的底线。母棋要放在同时压到两条线的位置，从那里用手指弹出。","开局时，把皇后放在棋盘正中，白子和黑子围成花形。第一击打散这朵“花”的开球，就是比赛的开始。"],"cap":["克朗棋的棋盘与开局摆法。正中是红色皇后，白子和黑子像花一样围在四周。四角是袋，每边的双线是底线，蓝圈的母棋放在近侧底线上"]},{"h":"弹击与反弹","p":["母棋基本上用指甲弹出，也有人用中指、食指或拇指。打进自己的棋子就能接着打，没打进就轮到对方。","棋盘的边框弹性很好，所以人们像打台球一样利用反弹来瞄准。把母棋打进袋里算犯规，会受到处罚。"],"cap":["用手指弹出母棋（蓝），在右边框反弹后撞上白子，把白子打进右上角的袋（红）。无法直接瞄准的棋子，借助边框也能打到"]},{"h":"弹击游戏的伙伴们","p":["世界各地都有类似克朗棋的“弹击”游戏。加拿大的克罗基诺尔是瞄准圆盘中央小洞的游戏，皮舍诺特也一直在加拿大流行。据说19世纪末，从亚洲回来的传教士把克朗棋带到了北美。","拉脱维亚和爱沙尼亚的诺乌斯据说诞生于1920年代，不用手指，而是用小球杆击打圆片。它成了拉脱维亚最受欢迎的运动之一，1993年起还举办国际锦标赛。"],"cap":["用手指或球杆弹击的棋盘游戏的伙伴：加拿大的克罗基诺尔和皮舍诺特、拉脱维亚和爱沙尼亚的诺乌斯、北欧的库罗纳，都和克朗棋很像"]},{"h":"计分与世界大赛","p":["按国际规则，掩护皇后可加3分，先得25分者获胜。家里玩时还有很多地方规则，比如把皇后算作5分。","据说斯里兰卡在1935年前后开始有正式比赛，到1958年，印度和斯里兰卡已有官方协会。1988年国际克朗棋联合会（ICF）在金奈成立，世界锦标赛从1991年开始举办。"],"cap":[]}],"tl":[["20世纪初","印度举办邦级比赛"],["1935年前后","据说斯里兰卡开始有正式比赛"],["1958","印度和斯里兰卡已有官方协会"],["1988","国际克朗棋联合会在金奈成立"],["1991","第1届世界克朗棋锦标赛"]],"figL":{"family":[["克朗棋","印度・南亚"],["克罗基诺尔","加拿大"],["皮舍诺特","加拿大"],["诺乌斯","拉脱维亚・爱沙尼亚"],["库罗纳","瑞典・丹麦"]]}}};
